-- ======================================================== 0003_rate_limits.sql
-- Fixed-window rate limiting for auth endpoints (PRODUCTION-BRIEF §3.1).
-- Called only by the server with the service role.

create table if not exists public.rate_limits (
  key          text primary key,
  hits         int not null,
  window_start timestamptz not null
);
alter table public.rate_limits enable row level security;
revoke all on public.rate_limits from anon, authenticated;

-- Returns true while the caller is within p_max hits per p_window_seconds.
create or replace function public.consume_rate_limit(p_key text, p_max int, p_window_seconds int)
returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_hits int;
begin
  insert into public.rate_limits as rl (key, hits, window_start)
  values (p_key, 1, now())
  on conflict (key) do update set
    hits = case when rl.window_start <= now() - make_interval(secs => p_window_seconds)
                then 1 else rl.hits + 1 end,
    window_start = case when rl.window_start <= now() - make_interval(secs => p_window_seconds)
                then now() else rl.window_start end
  returning hits into v_hits;
  return v_hits <= p_max;
end $$;

revoke execute on function public.consume_rate_limit(text, int, int) from public, anon, authenticated;
grant execute on function public.consume_rate_limit(text, int, int) to service_role;


-- ======================================================== 0004_ledger_month_close.sql
-- Capital 50 AI — Phase 2: holdings, append-only ledger, month close (PRODUCTION-BRIEF §4, §5.1)
-- Balances are sums of ledger_entries. Nothing ever updates or deletes a ledger row.
-- Safe to re-run.

-- ------------------------------------------------------------------ holdings
create table if not exists public.holdings (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users(id) on delete restrict,
  strategy_id uuid not null references public.strategies(id),
  opened_at   timestamptz not null default now(),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (user_id, strategy_id)
);

drop trigger if exists holdings_updated on public.holdings;
create trigger holdings_updated before update on public.holdings
  for each row execute function public.set_updated_at();

-- ------------------------------------------------------------ ledger_entries
do $$ begin
  create type public.ledger_type as enum
    ('deposit', 'withdrawal', 'profit', 'loss', 'fee', 'affiliate_commission', 'affiliate_payout', 'adjustment');
exception when duplicate_object then null; end $$;

-- `ym` is the month an entry belongs to. For a deposit or withdrawal it is the first month the
-- money counts in; for profit/loss/fee it is the month that was closed.
create table if not exists public.ledger_entries (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users(id) on delete restrict,
  holding_id      uuid references public.holdings(id) on delete restrict,
  type            public.ledger_type not null,
  amount          numeric(18,2) not null check (amount <> 0),
  ym              date not null check (extract(day from ym) = 1),
  ref_type        text,
  ref_id          text,
  idempotency_key text not null unique,
  meta            jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now(),
  constraint ledger_sign check (
    (type in ('deposit', 'profit', 'affiliate_commission') and amount > 0) or
    (type in ('withdrawal', 'loss', 'fee', 'affiliate_payout') and amount < 0) or
    type = 'adjustment'),
  constraint ledger_holding_required check (
    holding_id is not null or type in ('affiliate_commission', 'affiliate_payout', 'adjustment'))
);
create index if not exists ledger_entries_user_ym on public.ledger_entries (user_id, ym);
create index if not exists ledger_entries_holding_ym on public.ledger_entries (holding_id, ym);

-- ------------------------------------------------------------- month_closes
create table if not exists public.month_closes (
  ym           date primary key check (extract(day from ym) = 1),
  closed_at    timestamptz not null default now(),
  closed_by    uuid references auth.users(id),
  holdings     int not null,
  total_profit numeric(18,2) not null,
  total_fees   numeric(18,2) not null
);

-- ---------------------------------------------------------- ledger guards
-- Append-only. The only exception is purge_demo_data(), which sets a transaction-local flag.
create or replace function public.ledger_append_only() returns trigger
language plpgsql as $$
begin
  if current_setting('c50.ledger_purge', true) = 'on' then
    return old;
  end if;
  raise exception 'ledger_entries is append-only';
end $$;

drop trigger if exists ledger_no_change on public.ledger_entries;
create trigger ledger_no_change before update or delete on public.ledger_entries
  for each row execute function public.ledger_append_only();
drop trigger if exists ledger_no_truncate on public.ledger_entries;
create trigger ledger_no_truncate before truncate on public.ledger_entries
  for each statement execute function public.audit_log_immutable();

-- Money can't be added to (or taken from) a month that is already closed, and a deposit can't
-- slip in while a close is running.
create or replace function public.ledger_check_open_month() returns trigger
language plpgsql as $$
declare
  v_last date;
begin
  if new.type in ('deposit', 'withdrawal') then
    perform pg_advisory_xact_lock(hashtext('c50.month_close'));
    select max(ym) into v_last from public.month_closes;
    if v_last is not null and new.ym <= v_last then
      raise exception 'Month % is already closed; % must count from a later month',
        to_char(new.ym, 'YYYY-MM'), new.type;
    end if;
  end if;
  return new;
end $$;

drop trigger if exists ledger_open_month on public.ledger_entries;
create trigger ledger_open_month before insert on public.ledger_entries
  for each row execute function public.ledger_check_open_month();

-- -------------------------------------------------------------- month close
-- For each holding open in month p_ym, with r = the published return for that strategy/month:
--   value_start = everything before p_ym + deposits/withdrawals that count from p_ym
--   profit      = round(value_start × r / 100, 2)          (negative = loss)
--   fee         = round(max(0, profit) × 2.5%, 2)
-- Writes profit|loss and fee entries keyed close:{ym}:{holding}:{type}. Re-running is a no-op.
-- Affiliate commissions: affiliate_on_fee() per fee, affiliate_settle_deposits() at the end (0008).
create or replace function public.close_month(p_ym date, p_actor uuid default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_ym     text := to_char(p_ym, 'YYYY-MM');
  v_last   date;
  h        record;
  v_start  numeric(18,2);
  v_r      numeric(7,3);
  v_profit numeric(18,2);
  v_fee    numeric(18,2);
  v_n      int := 0;
  v_tp     numeric(18,2) := 0;
  v_tf     numeric(18,2) := 0;
  v_result jsonb;
begin
  if p_ym is null or extract(day from p_ym) <> 1 then
    raise exception 'close_month needs the first day of a month, got %', p_ym;
  end if;
  perform pg_advisory_xact_lock(hashtext('c50.month_close'));

  if exists (select 1 from month_closes where ym = p_ym) then
    select jsonb_build_object('ym', v_ym, 'already_closed', true, 'holdings', holdings,
                              'total_profit', total_profit, 'total_fees', total_fees)
      into v_result from month_closes where ym = p_ym;
    return v_result;
  end if;

  select max(ym) into v_last from month_closes;
  if v_last is not null and p_ym < v_last then
    raise exception 'Cannot close %: % is already closed', v_ym, to_char(v_last, 'YYYY-MM');
  end if;
  -- no gaps: every month after the first close must be closed in order
  if v_last is not null and p_ym <> (v_last + interval '1 month')::date then
    raise exception 'Close % first', to_char(v_last + interval '1 month', 'YYYY-MM');
  end if;
  if p_ym >= date_trunc('month', now() at time zone 'Asia/Karachi')::date then
    raise exception 'Cannot close %: the month has not ended yet', v_ym;
  end if;

  for h in
    select ho.id, ho.user_id, ho.strategy_id, s.slug
      from holdings ho join strategies s on s.id = ho.strategy_id
     order by ho.id
  loop
    select coalesce(sum(amount), 0) into v_start
      from ledger_entries
     where holding_id = h.id
       and (ym < p_ym or (ym = p_ym and type in ('deposit', 'withdrawal')));
    continue when v_start <= 0;

    select return_pct into v_r from strategy_returns
     where strategy_id = h.strategy_id and ym = p_ym and status = 'published';
    if v_r is null then
      raise exception 'No published % return for %; publish it before closing the month', h.slug, v_ym;
    end if;

    v_profit := round(v_start * v_r / 100, 2);
    v_fee    := round(greatest(v_profit, 0) * 0.025, 2);

    if v_profit <> 0 then
      insert into ledger_entries (user_id, holding_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
      values (h.user_id, h.id, case when v_profit > 0 then 'profit' else 'loss' end::ledger_type, v_profit, p_ym,
              'month_close', v_ym,
              format('close:%s:%s:%s', v_ym, h.id, case when v_profit > 0 then 'profit' else 'loss' end),
              jsonb_build_object('r', v_r, 'value_start', v_start))
      on conflict (idempotency_key) do nothing;
    end if;
    if v_fee > 0 then
      insert into ledger_entries (user_id, holding_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
      values (h.user_id, h.id, 'fee', -v_fee, p_ym, 'month_close', v_ym,
              format('close:%s:%s:fee', v_ym, h.id),
              jsonb_build_object('rate', 0.025, 'profit', v_profit))
      on conflict (idempotency_key) do nothing;
    end if;

    if v_fee > 0 then perform affiliate_on_fee(h.user_id, h.id, p_ym, v_fee); end if;  -- 0008_affiliates

    v_n  := v_n + 1;
    v_tp := v_tp + v_profit;
    v_tf := v_tf + v_fee;
  end loop;

  perform affiliate_settle_deposits(p_ym);  -- 0008_affiliates: deposit commissions whose first month closed

  insert into month_closes (ym, closed_by, holdings, total_profit, total_fees)
  values (p_ym, p_actor, v_n, v_tp, v_tf);

  v_result := jsonb_build_object('ym', v_ym, 'already_closed', false, 'holdings', v_n,
                                 'total_profit', v_tp, 'total_fees', v_tf);
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_actor, case when p_actor is null then 'system' else 'staff' end,
          'month.close', 'month_closes', v_ym, v_result);
  return v_result;
end $$;

-- ------------------------------------------------------------- demo purge
-- Removes the demo investor (mobile 300 1234567) and every ledger row it has. Run before launch:
--   select public.purge_demo_data();
create or replace function public.purge_demo_data() returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid;
begin
  select id into v_uid from auth.users where phone = '923001234567';
  if v_uid is null then return; end if;
  perform set_config('c50.ledger_purge', 'on', true);
  delete from ledger_entries where user_id = v_uid;
  delete from holdings where user_id = v_uid;
  delete from auth.users where id = v_uid;
  perform set_config('c50.ledger_purge', 'off', true);
  insert into audit_log (actor_role, action, entity, entity_id, reason)
  values ('system', 'demo.purge', 'auth.users', v_uid::text, 'Demo account and sample money removed');
end $$;

-- ---------------------------------------------------------------------- RLS
alter table public.holdings       enable row level security;
alter table public.ledger_entries enable row level security;
alter table public.month_closes   enable row level security;

drop policy if exists holdings_own_read on public.holdings;
create policy holdings_own_read on public.holdings
  for select to authenticated using (user_id = auth.uid());

drop policy if exists ledger_own_read on public.ledger_entries;
create policy ledger_own_read on public.ledger_entries
  for select to authenticated using (user_id = auth.uid());

drop policy if exists month_closes_read on public.month_closes;
create policy month_closes_read on public.month_closes
  for select to authenticated using (true);

revoke insert, update, delete on public.holdings, public.ledger_entries, public.month_closes
  from anon, authenticated;
revoke execute on function public.close_month(date, uuid) from public, anon, authenticated;
revoke execute on function public.purge_demo_data() from public, anon, authenticated;
grant execute on function public.close_month(date, uuid) to service_role;


-- ======================================================== 0005_kyc_staff.sql
-- Capital 50 AI — Phase 3: KYC applications, documents (private storage), staff and the review decision.
-- PRODUCTION-BRIEF §3.6, §5.6, §6.2. Safe to re-run.

-- ---------------------------------------------------------------------- staff
do $$ begin
  create type public.staff_role as enum ('owner', 'compliance', 'finance', 'support');
exception when duplicate_object then null; end $$;

create table if not exists public.staff_members (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  role       public.staff_role not null,
  active     boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
drop trigger if exists staff_members_updated on public.staff_members;
create trigger staff_members_updated before update on public.staff_members
  for each row execute function public.set_updated_at();

-- Make an existing email login a staff member:  select public.grant_staff('you@example.com', 'owner');
create or replace function public.grant_staff(p_email text, p_role public.staff_role) returns text
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid;
begin
  select id into v_uid from auth.users where lower(email) = lower(trim(p_email));
  if v_uid is null then
    raise exception 'No login with email %. Create it first in Authentication > Users > Add user.', p_email;
  end if;
  insert into staff_members (user_id, role, active) values (v_uid, p_role, true)
  on conflict (user_id) do update set role = excluded.role, active = true;
  insert into audit_log (actor_role, action, entity, entity_id, after)
  values ('system', 'staff.grant', 'staff_members', v_uid::text, jsonb_build_object('email', p_email, 'role', p_role));
  return format('%s is now %s staff. They sign in at /admin/login.', p_email, p_role);
end $$;

-- ------------------------------------------------------------- applications
do $$ begin
  create type public.kyc_status as enum ('draft', 'review', 'verified', 'rejected');
exception when duplicate_object then null; end $$;

-- One row per attempt; history is kept. The latest row is the current one.
create table if not exists public.kyc_applications (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete restrict,
  status           public.kyc_status not null default 'draft',
  personal         jsonb not null default '{}'::jsonb,
  financial        jsonb not null default '{}'::jsonb,
  pep              boolean,
  edd              boolean not null default false,
  cnic_hash        text,
  provider_ref     text,
  provider_result  jsonb,
  rejection_reason text,
  submitted_at     timestamptz,
  decided_at       timestamptz,
  decided_by       uuid references auth.users(id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index if not exists kyc_applications_user on public.kyc_applications (user_id, created_at desc);
create index if not exists kyc_applications_status on public.kyc_applications (status, submitted_at);
-- One CNIC, one investor: no two people can be under review or verified with the same CNIC.
create unique index if not exists kyc_applications_cnic_once on public.kyc_applications (cnic_hash)
  where status in ('review', 'verified');
-- At most one open (draft or review) application per investor.
create unique index if not exists kyc_applications_one_open on public.kyc_applications (user_id)
  where status in ('draft', 'review');

drop trigger if exists kyc_applications_updated on public.kyc_applications;
create trigger kyc_applications_updated before update on public.kyc_applications
  for each row execute function public.set_updated_at();

do $$ begin
  create type public.kyc_doc_kind as enum ('cnic_front', 'cnic_back', 'selfie');
exception when duplicate_object then null; end $$;

create table if not exists public.kyc_documents (
  id             uuid primary key default gen_random_uuid(),
  application_id uuid not null references public.kyc_applications(id) on delete restrict,
  user_id        uuid not null references auth.users(id) on delete restrict,
  kind           public.kyc_doc_kind not null,
  storage_path   text not null unique,
  mime           text not null,
  size_bytes     int not null,
  sha256         text not null,
  created_at     timestamptz not null default now()
);
create index if not exists kyc_documents_app on public.kyc_documents (application_id, kind, created_at desc);

-- Private bucket. Only the server (service role) reads or writes it; staff get 5-minute signed links.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('kyc', 'kyc', false, 5242880, array['image/jpeg', 'image/png', 'application/pdf'])
on conflict (id) do update set public = false, file_size_limit = 5242880,
  allowed_mime_types = array['image/jpeg', 'image/png', 'application/pdf'];

-- ------------------------------------------------------------- the decision
-- Approve or reject an application under review. Only active owner/compliance staff.
-- Approval copies the CNIC name and city onto the profile (the name is locked from then on).
create or replace function public.kyc_decide(p_application uuid, p_staff uuid, p_approve boolean, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_app   kyc_applications%rowtype;
  v_role  staff_role;
  v_after jsonb;
begin
  select role into v_role from staff_members where user_id = p_staff and active;
  if v_role is null or v_role not in ('owner', 'compliance') then
    raise exception 'Only owner or compliance staff can decide KYC';
  end if;

  select * into v_app from kyc_applications where id = p_application for update;
  if not found then raise exception 'Application not found'; end if;
  if v_app.status <> 'review' then
    raise exception 'Application is %, not under review', v_app.status;
  end if;
  if not p_approve and length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'A rejection needs a reason the investor can act on';
  end if;
  if p_approve and v_app.user_id = p_staff then
    raise exception 'Staff cannot approve their own application';
  end if;

  update kyc_applications
     set status = case when p_approve then 'verified' else 'rejected' end::kyc_status,
         rejection_reason = case when p_approve then null else trim(p_reason) end,
         decided_at = now(), decided_by = p_staff
   where id = p_application;

  if p_approve then
    update profiles set full_name = v_app.personal->>'fullName', city = v_app.personal->>'city'
     where user_id = v_app.user_id;
  end if;

  v_after := jsonb_build_object('status', case when p_approve then 'verified' else 'rejected' end,
                                'reason', case when p_approve then null else trim(p_reason) end,
                                'pep', v_app.pep);
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, before, after, reason)
  values (p_staff, v_role::text, case when p_approve then 'kyc.approve' else 'kyc.reject' end,
          'kyc_applications', p_application::text, jsonb_build_object('status', v_app.status), v_after,
          nullif(trim(coalesce(p_reason, '')), ''));
  return v_after;
end $$;

-- ---------------------------------------------------------------------- RLS
alter table public.staff_members    enable row level security;
alter table public.kyc_applications enable row level security;
alter table public.kyc_documents    enable row level security;

drop policy if exists kyc_own_read on public.kyc_applications;
create policy kyc_own_read on public.kyc_applications
  for select to authenticated using (user_id = auth.uid());
drop policy if exists kyc_docs_own_read on public.kyc_documents;
create policy kyc_docs_own_read on public.kyc_documents
  for select to authenticated using (user_id = auth.uid());

revoke all on public.staff_members from anon, authenticated;
revoke insert, update, delete on public.kyc_applications, public.kyc_documents from anon, authenticated;
revoke execute on function public.kyc_decide(uuid, uuid, boolean, text) from public, anon, authenticated;
revoke execute on function public.grant_staff(text, public.staff_role) from public, anon, authenticated;
grant execute on function public.kyc_decide(uuid, uuid, boolean, text) to service_role;


-- ======================================================== 0006_deposits.sql
-- Capital 50 AI — Phase 4: deposits (PRODUCTION-BRIEF §5.4). Safe to re-run.
-- A deposit is credited exactly once, only by credit_deposit(): from a signature-verified provider
-- notification or from two-person staff confirmation of a bank transfer. Never from a browser redirect.

do $$ begin
  create type public.deposit_method as enum ('jazzcash', 'easypaisa', 'bank', 'usdt');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.deposit_status as enum ('pending', 'paid', 'failed', 'expired', 'refunded');
exception when duplicate_object then null; end $$;

create table if not exists public.deposits (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete restrict,
  strategy_id   uuid not null references public.strategies(id),
  amount        numeric(18,2) not null check (amount >= 5000 and amount <= 10000000),
  method        public.deposit_method not null,
  status        public.deposit_status not null default 'pending',
  reference     text not null unique,              -- our order reference (bank memo / provider order id)
  provider_ref  text unique,                       -- provider's transaction id, once known
  mode          text not null default 'sandbox' check (mode in ('sandbox', 'live')),
  meta          jsonb not null default '{}'::jsonb, -- e.g. USDT rate and invoice
  approvals     jsonb not null default '[]'::jsonb, -- bank transfer confirmations
  status_note   text,
  paid_at       timestamptz,
  effective_ym  date,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists deposits_user on public.deposits (user_id, created_at desc);
create index if not exists deposits_pending on public.deposits (method, status, created_at);

drop trigger if exists deposits_updated on public.deposits;
create trigger deposits_updated before update on public.deposits
  for each row execute function public.set_updated_at();

-- Every provider notification and staff action, exactly as received. Append-only.
create table if not exists public.payment_events (
  id           uuid primary key default gen_random_uuid(),
  provider     text not null,
  deposit_id   uuid references public.deposits(id),
  signature_ok boolean not null,
  outcome      text not null,
  payload      jsonb not null,
  received_at  timestamptz not null default now()
);
create index if not exists payment_events_deposit on public.payment_events (deposit_id, received_at);
drop trigger if exists payment_events_no_change on public.payment_events;
create trigger payment_events_no_change before update or delete on public.payment_events
  for each row execute function public.audit_log_immutable();

-- Company settings readable by the server (e.g. the bank account investors pay into).
create table if not exists public.app_settings (
  key        text primary key,
  value      jsonb not null,
  updated_at timestamptz not null default now()
);
insert into public.app_settings (key, value) values
  ('bank_account', '{"bank":"","title":"","iban":"","note":"Set your company bank account: update app_settings where key = ''bank_account''."}')
on conflict (key) do nothing;

-- ------------------------------------------------------------- credit
-- Money paid during a month starts earning the next month (brief §5.1 rule 6). One place to change it.
create or replace function public.deposit_effective_ym(p_paid_at timestamptz) returns date
language sql stable as $$
  select (date_trunc('month', p_paid_at at time zone 'Asia/Karachi') + interval '1 month')::date
$$;

-- Marks a pending deposit paid and writes its ledger entry. Calling it again returns the same
-- result and writes nothing (so replayed notifications are harmless).
create or replace function public.credit_deposit(p_deposit uuid, p_actor uuid, p_source text, p_provider_ref text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  d       deposits%rowtype;
  v_hold  uuid;
  v_ym    date;
  v_now   timestamptz := now();
begin
  select * into d from deposits where id = p_deposit for update;
  if not found then raise exception 'Deposit not found'; end if;
  if d.status = 'paid' then
    return jsonb_build_object('status', 'paid', 'already', true, 'effective_ym', to_char(d.effective_ym, 'YYYY-MM'));
  end if;
  if d.status <> 'pending' then
    raise exception 'Deposit % is %, not pending', d.reference, d.status;
  end if;
  -- one provider transaction can only ever pay for one deposit
  if p_provider_ref is not null and exists (select 1 from deposits where provider_ref = p_provider_ref and id <> d.id) then
    raise exception 'Payment % was already used for deposit %', p_provider_ref,
      (select reference from deposits where provider_ref = p_provider_ref and id <> d.id limit 1);
  end if;

  v_ym := deposit_effective_ym(v_now);
  insert into holdings (user_id, strategy_id) values (d.user_id, d.strategy_id)
  on conflict (user_id, strategy_id) do nothing;
  select id into v_hold from holdings where user_id = d.user_id and strategy_id = d.strategy_id;

  update deposits set status = 'paid', paid_at = v_now, effective_ym = v_ym,
         provider_ref = coalesce(p_provider_ref, provider_ref)
   where id = d.id;

  insert into ledger_entries (user_id, holding_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
  values (d.user_id, v_hold, 'deposit', d.amount, v_ym, 'deposit', d.id::text, 'dep:' || d.id,
          jsonb_build_object('method', d.method, 'reference', d.reference, 'source', p_source,
                             'day', extract(day from v_now at time zone 'Asia/Karachi')::int));

  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_actor, case when p_actor is null then 'system' else 'staff' end, 'deposit.credit', 'deposits', d.id::text,
          jsonb_build_object('amount', d.amount, 'method', d.method, 'source', p_source,
                             'provider_ref', p_provider_ref, 'effective_ym', to_char(v_ym, 'YYYY-MM')));
  perform affiliate_on_deposit(d.id, v_ym);  -- 0008_affiliates (only when a deposit rate is set)
  return jsonb_build_object('status', 'paid', 'already', false, 'effective_ym', to_char(v_ym, 'YYYY-MM'));
end $$;

-- Pending -> failed/expired (from a verified provider notification or staff). Paid deposits are untouched.
create or replace function public.close_deposit(p_deposit uuid, p_status deposit_status, p_actor uuid, p_note text)
returns text
language plpgsql security definer set search_path = public as $$
declare
  d deposits%rowtype;
begin
  if p_status not in ('failed', 'expired') then raise exception 'close_deposit only fails or expires'; end if;
  select * into d from deposits where id = p_deposit for update;
  if not found then raise exception 'Deposit not found'; end if;
  if d.status <> 'pending' then return d.status::text; end if;
  update deposits set status = p_status, status_note = p_note where id = d.id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after, reason)
  values (p_actor, case when p_actor is null then 'system' else 'staff' end, 'deposit.' || p_status, 'deposits',
          d.id::text, jsonb_build_object('amount', d.amount, 'method', d.method), p_note);
  return p_status::text;
end $$;

-- Bank transfers: two different owner/finance staff confirm the same bank statement reference.
-- The second confirmation credits the deposit.
create or replace function public.confirm_bank_deposit(p_deposit uuid, p_staff uuid, p_bank_ref text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  d      deposits%rowtype;
  v_role staff_role;
  v_ref  text := upper(regexp_replace(coalesce(p_bank_ref, ''), '\s', '', 'g'));
  v_first jsonb;
begin
  select role into v_role from staff_members where user_id = p_staff and active;
  if v_role is null or v_role not in ('owner', 'finance') then
    raise exception 'Only owner or finance staff can confirm bank deposits';
  end if;
  if length(v_ref) < 4 then raise exception 'Enter the transaction reference from the bank statement'; end if;

  select * into d from deposits where id = p_deposit for update;
  if not found then raise exception 'Deposit not found'; end if;
  if d.method <> 'bank' then raise exception 'Not a bank transfer'; end if;
  if d.status <> 'pending' then raise exception 'Deposit is %, not pending', d.status; end if;
  if d.user_id = p_staff then raise exception 'Staff cannot confirm their own deposit'; end if;
  -- one bank transaction can only ever pay for one deposit
  if exists (select 1 from deposits where provider_ref = 'BANK:' || v_ref and id <> d.id) then
    raise exception 'Bank reference % was already used for deposit %', v_ref,
      (select reference from deposits where provider_ref = 'BANK:' || v_ref and id <> d.id limit 1);
  end if;

  v_first := d.approvals -> 0;
  if v_first is null then
    update deposits set approvals = jsonb_build_array(jsonb_build_object('staff', p_staff, 'bank_ref', v_ref, 'at', now()))
     where id = d.id;
    insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
    values (p_staff, v_role::text, 'deposit.bank_confirm_1', 'deposits', d.id::text, jsonb_build_object('bank_ref', v_ref));
    return jsonb_build_object('status', 'pending', 'confirmations', 1);
  end if;

  if (v_first->>'staff')::uuid = p_staff then
    raise exception 'A second, different staff member must confirm this deposit';
  end if;
  if v_first->>'bank_ref' <> v_ref then
    raise exception 'Bank reference does not match the first confirmation (%)', v_first->>'bank_ref';
  end if;
  update deposits set approvals = approvals || jsonb_build_array(jsonb_build_object('staff', p_staff, 'bank_ref', v_ref, 'at', now()))
   where id = d.id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_staff, v_role::text, 'deposit.bank_confirm_2', 'deposits', d.id::text, jsonb_build_object('bank_ref', v_ref));
  return credit_deposit(d.id, p_staff, 'bank_two_person', 'BANK:' || v_ref);
end $$;

-- ---------------------------------------------------------------------- RLS
alter table public.deposits       enable row level security;
alter table public.payment_events enable row level security;
alter table public.app_settings   enable row level security;

drop policy if exists deposits_own_read on public.deposits;
create policy deposits_own_read on public.deposits
  for select to authenticated using (user_id = auth.uid());

revoke insert, update, delete on public.deposits from anon, authenticated;
revoke all on public.payment_events, public.app_settings from anon, authenticated;
revoke execute on function public.credit_deposit(uuid, uuid, text, text),
                           public.close_deposit(uuid, deposit_status, uuid, text),
                           public.confirm_bank_deposit(uuid, uuid, text)
  from public, anon, authenticated;
grant execute on function public.credit_deposit(uuid, uuid, text, text),
                          public.close_deposit(uuid, deposit_status, uuid, text),
                          public.confirm_bank_deposit(uuid, uuid, text)
  to service_role;


-- ======================================================== 0007_withdrawals.sql
-- Capital 50 AI — Phase 5: payout methods and withdrawals (PRODUCTION-BRIEF §3.4, §5.5). Safe to re-run.
-- Money leaves the ledger only in pay_withdrawal(): after KYC, a 24-hour-old payout method in the
-- investor's verified name, an SMS code, staff approval (two people above the threshold) and a
-- payment reference. Every step is audit-logged.

do $$ begin
  create type public.payout_type as enum ('jazz', 'easy', 'bank', 'usdt');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.withdrawal_status as enum ('requested', 'approved', 'paid', 'rejected', 'cancelled');
exception when duplicate_object then null; end $$;

create table if not exists public.payout_methods (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users(id) on delete restrict,
  type           public.payout_type not null,
  account_enc    text not null,                 -- AES-256-GCM, key held by the server (C50_DATA_KEY)
  account_hint   text not null,                 -- e.g. "0300 •••• 4567", safe to show
  account_hash   text not null,                 -- keyed hash, to spot the same account twice
  bank           text,
  title          text not null,
  title_verified boolean not null default false,
  ready_at       timestamptz not null default now() + interval '24 hours',
  disabled_at    timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index if not exists payout_methods_user on public.payout_methods (user_id);
create unique index if not exists payout_methods_once on public.payout_methods (user_id, account_hash) where disabled_at is null;
drop trigger if exists payout_methods_updated on public.payout_methods;
create trigger payout_methods_updated before update on public.payout_methods
  for each row execute function public.set_updated_at();

create table if not exists public.withdrawals (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete restrict,
  payout_method_id uuid not null references public.payout_methods(id),
  amount           numeric(18,2) not null check (amount >= 1000),
  status           public.withdrawal_status not null default 'requested',
  needs_approvals  int not null check (needs_approvals in (1, 2)),
  approvals        jsonb not null default '[]'::jsonb,
  tx_ref           text unique,
  reason           text,
  otp_verified_at  timestamptz not null,
  paid_at          timestamptz,
  paid_by          uuid references auth.users(id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index if not exists withdrawals_user on public.withdrawals (user_id, created_at desc);
create index if not exists withdrawals_open on public.withdrawals (status, created_at);
drop trigger if exists withdrawals_updated on public.withdrawals;
create trigger withdrawals_updated before update on public.withdrawals
  for each row execute function public.set_updated_at();

insert into public.app_settings (key, value) values ('withdrawal_two_approvals_above', '100000')
on conflict (key) do nothing;

-- ------------------------------------------------------------- balances
create or replace function public.ledger_balance(p_user uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(sum(amount), 0) from ledger_entries where user_id = p_user
$$;

-- What the investor can withdraw now: the ledger balance minus withdrawals already requested/approved.
create or replace function public.available_to_withdraw(p_user uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select ledger_balance(p_user)
       - coalesce((select sum(amount) from withdrawals where user_id = p_user and status in ('requested', 'approved')), 0)
$$;

create or replace function public.kyc_verified(p_user uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select status = 'verified' from kyc_applications where user_id = p_user
                   order by created_at desc limit 1), false)
$$;

-- ------------------------------------------------------------- request
create or replace function public.request_withdrawal(p_user uuid, p_method uuid, p_amount numeric, p_otp_at timestamptz)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  m        payout_methods%rowtype;
  v_limit  numeric;
  v_id     uuid;
begin
  perform pg_advisory_xact_lock(hashtext('c50.wd.' || p_user));  -- one money action per investor at a time
  if not kyc_verified(p_user) then raise exception 'Verify your identity (CNIC) before withdrawing'; end if;
  if account_frozen(p_user) then raise exception 'Your account is on hold. Please contact support.'; end if;
  if p_otp_at is null or p_otp_at < now() - interval '10 minutes' then raise exception 'Confirm with the code sent to your phone'; end if;
  select * into m from payout_methods where id = p_method and user_id = p_user and disabled_at is null;
  if not found then raise exception 'Choose one of your payout methods'; end if;
  if m.ready_at > now() then raise exception 'This payout method unlocks at %', to_char(m.ready_at at time zone 'Asia/Karachi', 'DD Mon HH24:MI'); end if;
  if not m.title_verified then raise exception 'This account is not in your verified name'; end if;
  if p_amount is null or p_amount < 1000 then raise exception 'Minimum withdrawal is Rs 1,000'; end if;
  if p_amount <> round(p_amount, 2) then raise exception 'Invalid amount'; end if;
  if p_amount > available_to_withdraw(p_user) then raise exception 'That is more than your available balance'; end if;

  select coalesce((value #>> '{}')::numeric, 100000) into v_limit from app_settings where key = 'withdrawal_two_approvals_above';
  insert into withdrawals (user_id, payout_method_id, amount, needs_approvals, otp_verified_at)
  values (p_user, p_method, p_amount, case when p_amount > coalesce(v_limit, 100000) then 2 else 1 end, p_otp_at)
  returning id into v_id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_user, 'investor', 'withdrawal.request', 'withdrawals', v_id::text,
          jsonb_build_object('amount', p_amount, 'method', m.type, 'account', m.account_hint));
  return v_id;
end $$;

create or replace function public.cancel_withdrawal(p_user uuid, p_id uuid) returns text
language plpgsql security definer set search_path = public as $$
declare
  w withdrawals%rowtype;
begin
  select * into w from withdrawals where id = p_id and user_id = p_user for update;
  if not found then raise exception 'Withdrawal not found'; end if;
  if w.status <> 'requested' then raise exception 'This withdrawal is already %', w.status; end if;
  update withdrawals set status = 'cancelled' where id = p_id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_user, 'investor', 'withdrawal.cancel', 'withdrawals', p_id::text, jsonb_build_object('amount', w.amount));
  return 'cancelled';
end $$;

-- ------------------------------------------------------------- staff
create or replace function public.staff_money_role(p_staff uuid) returns staff_role
language plpgsql stable security definer set search_path = public as $$
declare v staff_role;
begin
  select role into v from staff_members where user_id = p_staff and active;
  if v is null or v not in ('owner', 'finance') then raise exception 'Only owner or finance staff can do this'; end if;
  return v;
end $$;

create or replace function public.approve_withdrawal(p_id uuid, p_staff uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_role staff_role := staff_money_role(p_staff);
  w      withdrawals%rowtype;
  v_n    int;
begin
  select * into w from withdrawals where id = p_id for update;
  if not found then raise exception 'Withdrawal not found'; end if;
  if w.status <> 'requested' then raise exception 'Withdrawal is %, not waiting for approval', w.status; end if;
  if w.user_id = p_staff then raise exception 'Staff cannot approve their own withdrawal'; end if;
  if exists (select 1 from jsonb_array_elements(w.approvals) a where (a->>'staff')::uuid = p_staff) then
    raise exception 'A second, different staff member must approve this withdrawal';
  end if;
  if not kyc_verified(w.user_id) then raise exception 'Investor is no longer KYC verified'; end if;
  if account_frozen(w.user_id) then raise exception 'Investor account is frozen'; end if;
  if ledger_balance(w.user_id) < (select sum(amount) from withdrawals where user_id = w.user_id and status in ('requested', 'approved')) then
    raise exception 'Balance no longer covers this withdrawal';
  end if;

  v_n := jsonb_array_length(w.approvals) + 1;
  update withdrawals
     set approvals = approvals || jsonb_build_array(jsonb_build_object('staff', p_staff, 'at', now())),
         status = case when v_n >= needs_approvals then 'approved'::withdrawal_status else status end
   where id = p_id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_staff, v_role::text, 'withdrawal.approve', 'withdrawals', p_id::text,
          jsonb_build_object('approvals', v_n, 'needed', w.needs_approvals, 'amount', w.amount));
  return jsonb_build_object('approvals', v_n, 'needed', w.needs_approvals,
                            'status', case when v_n >= w.needs_approvals then 'approved' else 'requested' end);
end $$;

create or replace function public.reject_withdrawal(p_id uuid, p_staff uuid, p_reason text) returns text
language plpgsql security definer set search_path = public as $$
declare
  v_role staff_role := staff_money_role(p_staff);
  w      withdrawals%rowtype;
begin
  if length(trim(coalesce(p_reason, ''))) < 5 then raise exception 'Give a reason the investor can act on'; end if;
  select * into w from withdrawals where id = p_id for update;
  if not found then raise exception 'Withdrawal not found'; end if;
  if w.status not in ('requested', 'approved') then raise exception 'Withdrawal is already %', w.status; end if;
  update withdrawals set status = 'rejected', reason = trim(p_reason) where id = p_id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after, reason)
  values (p_staff, v_role::text, 'withdrawal.reject', 'withdrawals', p_id::text, jsonb_build_object('amount', w.amount), trim(p_reason));
  return 'rejected';
end $$;

-- Money leaves here: split across the investor's holdings in proportion to their value, dated the
-- current month (withdrawn money does not earn that month's result). Waits until last month is closed,
-- so a loss can never be booked on money already paid out.
create or replace function public.pay_withdrawal(p_id uuid, p_staff uuid, p_tx_ref text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_role  staff_role := staff_money_role(p_staff);
  w       withdrawals%rowtype;
  v_ref   text := upper(regexp_replace(coalesce(p_tx_ref, ''), '\s', '', 'g'));
  v_ym    date := date_trunc('month', now() at time zone 'Asia/Karachi')::date;
  v_prev  date := (date_trunc('month', now() at time zone 'Asia/Karachi') - interval '1 month')::date;
  v_total numeric;
  v_aff   numeric;
  v_need  numeric;
  v_hold  numeric;
  v_left  numeric;
  v_share numeric;
  h       record;
  v_n     int;
  v_i     int := 0;
begin
  if length(v_ref) < 4 then raise exception 'Enter the payment transaction reference'; end if;
  select * into w from withdrawals where id = p_id for update;
  if not found then raise exception 'Withdrawal not found'; end if;
  if w.status = 'paid' then return jsonb_build_object('status', 'paid', 'already', true); end if;
  if w.status <> 'approved' then raise exception 'Withdrawal is %, it must be approved first', w.status; end if;
  if exists (select 1 from withdrawals where tx_ref = v_ref and id <> w.id) then
    raise exception 'Transaction reference % was already used for another withdrawal', v_ref;
  end if;
  perform pg_advisory_xact_lock(hashtext('c50.wd.' || w.user_id));
  if not kyc_verified(w.user_id) then raise exception 'Investor is no longer KYC verified'; end if;
  if account_frozen(w.user_id) then raise exception 'Investor account is frozen'; end if;
  if not exists (select 1 from payout_methods where id = w.payout_method_id and disabled_at is null and title_verified) then
    raise exception 'The payout method was removed or is not verified';
  end if;
  if not exists (select 1 from month_closes where ym = v_prev)
     and exists (select 1 from ledger_entries where user_id = w.user_id and ym <= v_prev) then
    raise exception 'Close % before paying withdrawals, so its result is booked first', to_char(v_prev, 'YYYY-MM');
  end if;

  -- affiliate earnings (no holding) are paid out first, the rest from holdings in proportion to value;
  -- the largest holding goes last and takes the rounding remainder
  select coalesce(sum(amount), 0) into v_aff from ledger_entries where user_id = w.user_id and holding_id is null;
  select coalesce(sum(value), 0), count(*) into v_total, v_n
    from (select sum(amount) as value from ledger_entries
           where user_id = w.user_id and holding_id is not null group by holding_id having sum(amount) > 0) x;
  if v_total + greatest(v_aff, 0) < w.amount then raise exception 'Balance no longer covers this withdrawal'; end if;

  v_left := w.amount;
  if v_aff > 0 then
    v_share := least(v_aff, w.amount);
    insert into ledger_entries (user_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
    values (w.user_id, 'affiliate_payout', -v_share, v_ym, 'withdrawal', w.id::text, format('wd:%s:aff', w.id),
            jsonb_build_object('source', 'withdrawal', 'tx_ref', v_ref, 'day', extract(day from now() at time zone 'Asia/Karachi')::int));
    v_left := v_left - v_share;
  end if;
  v_need := v_left;   -- what the holdings still have to cover
  v_hold := v_total;

  for h in select holding_id, sum(amount) as value from ledger_entries
            where user_id = w.user_id and holding_id is not null
            group by holding_id having sum(amount) > 0 order by 2, 1 loop
    v_i := v_i + 1;
    v_share := case when v_i = v_n then v_left else least(h.value, round(v_need * h.value / v_hold, 2)) end;
    if v_share > 0 then
      insert into ledger_entries (user_id, holding_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
      values (w.user_id, h.holding_id, 'withdrawal', -v_share, v_ym, 'withdrawal', w.id::text,
              format('wd:%s:%s', w.id, h.holding_id),
              jsonb_build_object('source', 'withdrawal', 'tx_ref', v_ref,
                                 'day', extract(day from now() at time zone 'Asia/Karachi')::int));
    end if;
    v_left := v_left - v_share;
  end loop;

  update withdrawals set status = 'paid', tx_ref = v_ref, paid_at = now(), paid_by = p_staff where id = w.id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_staff, v_role::text, 'withdrawal.paid', 'withdrawals', w.id::text,
          jsonb_build_object('amount', w.amount, 'tx_ref', v_ref, 'ym', to_char(v_ym, 'YYYY-MM')));
  return jsonb_build_object('status', 'paid', 'already', false);
end $$;

-- ---------------------------------------------------------------------- RLS
alter table public.payout_methods enable row level security;
alter table public.withdrawals    enable row level security;

drop policy if exists payout_methods_own_read on public.payout_methods;
create policy payout_methods_own_read on public.payout_methods
  for select to authenticated using (user_id = auth.uid());
drop policy if exists withdrawals_own_read on public.withdrawals;
create policy withdrawals_own_read on public.withdrawals
  for select to authenticated using (user_id = auth.uid());

-- investors never see the encrypted account or its hash, only the hint
revoke select on public.payout_methods from authenticated;
grant select (id, user_id, type, account_hint, bank, title, title_verified, ready_at, disabled_at, created_at)
  on public.payout_methods to authenticated;
revoke insert, update, delete on public.payout_methods, public.withdrawals from anon, authenticated;

revoke execute on function public.ledger_balance(uuid), public.available_to_withdraw(uuid), public.kyc_verified(uuid),
  public.request_withdrawal(uuid, uuid, numeric, timestamptz), public.cancel_withdrawal(uuid, uuid),
  public.staff_money_role(uuid), public.approve_withdrawal(uuid, uuid), public.reject_withdrawal(uuid, uuid, text),
  public.pay_withdrawal(uuid, uuid, text)
  from public, anon, authenticated;
grant execute on function public.ledger_balance(uuid), public.available_to_withdraw(uuid), public.kyc_verified(uuid),
  public.request_withdrawal(uuid, uuid, numeric, timestamptz), public.cancel_withdrawal(uuid, uuid),
  public.approve_withdrawal(uuid, uuid), public.reject_withdrawal(uuid, uuid, text), public.pay_withdrawal(uuid, uuid, text)
  to service_role;


-- ======================================================== 0008_affiliates.sql
-- Capital 50 AI — Phase 6: affiliates (PRODUCTION-BRIEF §3.5, §5.3) plus account freeze. Safe to re-run.
-- Commissions are company money paid to the affiliate; nothing is ever taken from a member.
--   fee share : affiliate_fee_share_rate (default 15%) of the 2.5% fee charged on a member's profit,
--               credited inside close_month().
--   deposits  : affiliate_deposit_rate (default 0%, owner sets it) of a member's deposit, pending until
--               the deposit's first month closes; void if the member withdraws before then.

alter table public.profiles add column if not exists affiliate_blocked_at timestamptz;
alter table public.profiles add column if not exists frozen_at timestamptz;
alter table public.profiles add column if not exists frozen_reason text;

insert into public.app_settings (key, value) values
  ('affiliate_fee_share_rate', '0.15'),
  ('affiliate_deposit_rate', '0')
on conflict (key) do nothing;

create or replace function public.setting_num(p_key text, p_default numeric) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce((select (value #>> '{}')::numeric from app_settings where key = p_key), p_default)
$$;

-- ------------------------------------------------------------- invite codes
-- Every code a person has ever used keeps resolving to them; a code can never pass to someone else.
create table if not exists public.affiliate_codes (
  code       text primary key check (code ~ '^[A-Z0-9]{4,12}$'),
  user_id    uuid not null references auth.users(id) on delete cascade,
  active     boolean not null default true,
  created_at timestamptz not null default now()
);
create index if not exists affiliate_codes_user on public.affiliate_codes (user_id);
insert into public.affiliate_codes (code, user_id)
  select referral_code, user_id from public.profiles on conflict (code) do nothing;

create or replace function public.make_referral_code(p_name text) returns text
language plpgsql as $$
declare
  base text := left(regexp_replace(upper(coalesce(p_name, '')), '[^A-Z]', '', 'g'), 6);
  candidate text;
begin
  if length(base) < 2 then base := 'C50'; end if;
  loop
    candidate := base || lpad((floor(random() * 90) + 10)::int::text, 2, '0');
    exit when not exists (select 1 from public.profiles where referral_code = candidate)
          and not exists (select 1 from public.affiliate_codes where code = candidate);
    base := left(base, 5) || chr(65 + floor(random() * 26)::int);
  end loop;
  return candidate;
end $$;

create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  meta     jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_phone  text  := case when new.phone is null or new.phone = '' then null
                         else '+' || ltrim(new.phone, '+') end;
  v_email  text  := nullif(lower(trim(coalesce(meta->>'email', new.email, ''))), '');
  v_ref    text  := upper(regexp_replace(coalesce(meta->>'ref', ''), '[^A-Za-z0-9]', '', 'g'));
  v_code   text  := public.make_referral_code(meta->>'full_name');
  v_referrer uuid;
  v_profile  uuid;
begin
  if v_ref <> '' then
    select p.id into v_referrer from public.affiliate_codes c join public.profiles p on p.user_id = c.user_id
     where c.code = v_ref and (p.phone is distinct from v_phone);   -- no self-referral
  end if;

  insert into public.profiles (user_id, full_name, phone, email, referral_code, referred_by, referred_at)
  values (new.id, trim(coalesce(meta->>'full_name', '')), v_phone, v_email, v_code, v_referrer,
          case when v_referrer is not null then now() end)
  returning id into v_profile;
  insert into public.affiliate_codes (code, user_id) values (v_code, new.id);

  insert into public.audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (new.id, 'investor', 'profile.create', 'profiles', v_profile::text,
          jsonb_build_object('phone', v_phone, 'referred_by', v_referrer, 'ref', nullif(v_ref, '')));
  return new;
end $$;

-- Change your invite code (4-12 letters/numbers). Old codes keep working for you.
create or replace function public.set_referral_code(p_user uuid, p_code text) returns text
language plpgsql security definer set search_path = public as $$
declare
  v text := upper(trim(coalesce(p_code, '')));
begin
  if v !~ '^[A-Z0-9]{4,12}$' then raise exception 'Use 4–12 letters or numbers, no spaces.'; end if;
  if v in ('ADMIN', 'CAPITAL50', 'SUPPORT', 'C50AI', 'CAPITAL', 'STAFF', 'OFFICIAL', 'C50') then raise exception 'That code is reserved.'; end if;
  if exists (select 1 from affiliate_codes where code = v and user_id <> p_user) then raise exception 'That code is taken. Try another.'; end if;
  insert into affiliate_codes (code, user_id) values (v, p_user) on conflict (code) do nothing;
  update profiles set referral_code = v where user_id = p_user;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_user, 'investor', 'affiliate.code', 'profiles', p_user::text, jsonb_build_object('code', v));
  return v;
end $$;

-- ------------------------------------------------------------- commissions
do $$ begin
  create type public.commission_kind as enum ('fee_share', 'deposit');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.commission_status as enum ('pending', 'credited', 'void');
exception when duplicate_object then null; end $$;

create table if not exists public.affiliate_commissions (
  id                uuid primary key default gen_random_uuid(),
  affiliate_id      uuid not null references auth.users(id) on delete restrict,
  member_id         uuid not null references auth.users(id) on delete restrict,
  kind              public.commission_kind not null,
  ym                date not null check (extract(day from ym) = 1),
  base_amount       numeric(18,2) not null,         -- the fee charged, or the deposit
  rate              numeric(6,4) not null,
  commission_amount numeric(18,2) not null check (commission_amount > 0),
  status            public.commission_status not null default 'pending',
  void_reason       text,
  source_id         text not null,
  idempotency_key   text not null unique,
  credited_at       timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index if not exists affiliate_commissions_aff on public.affiliate_commissions (affiliate_id, ym);
create index if not exists affiliate_commissions_member on public.affiliate_commissions (member_id);
drop trigger if exists affiliate_commissions_updated on public.affiliate_commissions;
create trigger affiliate_commissions_updated before update on public.affiliate_commissions
  for each row execute function public.set_updated_at();

-- The affiliate who referred this member, if commissions may be paid on them.
create or replace function public.commission_affiliate(p_member uuid) returns uuid
language sql stable security definer set search_path = public as $$
  select a.user_id from profiles m join profiles a on a.id = m.referred_by
   where m.user_id = p_member and a.affiliate_blocked_at is null and a.user_id <> m.user_id
$$;

-- Same verified CNIC on both sides = self-referral.
create or replace function public.same_person(p_a uuid, p_b uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from kyc_applications x join kyc_applications y on x.cnic_hash = y.cnic_hash
                  where x.user_id = p_a and y.user_id = p_b and x.status = 'verified' and y.status = 'verified')
$$;

create or replace function public.credit_commission(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare c affiliate_commissions%rowtype;
begin
  select * into c from affiliate_commissions where id = p_id for update;
  if c.status <> 'pending' then return; end if;
  insert into ledger_entries (user_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
  values (c.affiliate_id, 'affiliate_commission', c.commission_amount, c.ym, 'affiliate_commission', c.id::text,
          'affc:' || c.id, jsonb_build_object('kind', c.kind, 'member', c.member_id))
  on conflict (idempotency_key) do nothing;
  update affiliate_commissions set status = 'credited', credited_at = now() where id = p_id;
end $$;

-- Called by close_month() for each fee charged.
create or replace function public.affiliate_on_fee(p_member uuid, p_holding uuid, p_ym date, p_fee numeric) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_aff  uuid := commission_affiliate(p_member);
  v_rate numeric := setting_num('affiliate_fee_share_rate', 0.15);
  v_amt  numeric := round(p_fee * v_rate, 2);
  v_id   uuid;
begin
  if v_aff is null or v_amt <= 0 then return; end if;
  insert into affiliate_commissions (affiliate_id, member_id, kind, ym, base_amount, rate, commission_amount, source_id, idempotency_key,
                                     status, void_reason)
  values (v_aff, p_member, 'fee_share', p_ym, p_fee, v_rate, v_amt, p_holding::text,
          format('aff:fee:%s:%s', to_char(p_ym, 'YYYY-MM'), p_holding),
          case when same_person(v_aff, p_member) then 'void' else 'pending' end::commission_status,
          case when same_person(v_aff, p_member) then 'Self-referral (same CNIC)' end)
  on conflict (idempotency_key) do nothing
  returning id into v_id;
  if v_id is not null then perform credit_commission(v_id); end if;
end $$;

-- Called by credit_deposit(): pending until the deposit's first month closes.
create or replace function public.affiliate_on_deposit(p_deposit uuid, p_effective_ym date) returns void
language plpgsql security definer set search_path = public as $$
declare
  d      deposits%rowtype;
  v_aff  uuid;
  v_rate numeric := setting_num('affiliate_deposit_rate', 0);
begin
  if v_rate <= 0 then return; end if;
  select * into d from deposits where id = p_deposit;
  v_aff := commission_affiliate(d.user_id);
  if v_aff is null or round(d.amount * v_rate, 2) <= 0 then return; end if;
  insert into affiliate_commissions (affiliate_id, member_id, kind, ym, base_amount, rate, commission_amount, source_id, idempotency_key)
  values (v_aff, d.user_id, 'deposit', p_effective_ym, d.amount, v_rate, round(d.amount * v_rate, 2), d.id::text, 'aff:dep:' || d.id)
  on conflict (idempotency_key) do nothing;
end $$;

-- Called by close_month(): deposit commissions whose first month just closed are credited, unless the
-- member asked to withdraw since the deposit or it's a self-referral.
create or replace function public.affiliate_settle_deposits(p_ym date) returns void
language plpgsql security definer set search_path = public as $$
declare c record;
begin
  for c in select ac.*, d.paid_at from affiliate_commissions ac join deposits d on d.id::text = ac.source_id
            where ac.kind = 'deposit' and ac.status = 'pending' and ac.ym <= p_ym loop
    if exists (select 1 from withdrawals w where w.user_id = c.member_id and w.created_at >= c.paid_at
                and w.status in ('requested', 'approved', 'paid')) then
      update affiliate_commissions set status = 'void', void_reason = 'Member withdrew before the deposit''s first month closed' where id = c.id;
    elsif same_person(c.affiliate_id, c.member_id) then
      update affiliate_commissions set status = 'void', void_reason = 'Self-referral (same CNIC)' where id = c.id;
    else
      perform credit_commission(c.id);
    end if;
  end loop;
end $$;

-- Staff: void a commission. If it was already credited, a reversing adjustment is written (the ledger
-- is never edited).
create or replace function public.void_commission(p_id uuid, p_staff uuid, p_reason text) returns text
language plpgsql security definer set search_path = public as $$
declare
  c      affiliate_commissions%rowtype;
  v_role staff_role;
begin
  select role into v_role from staff_members where user_id = p_staff and active;
  if v_role is null or v_role not in ('owner', 'compliance', 'finance') then raise exception 'Only owner, compliance or finance staff can void commissions'; end if;
  if length(trim(coalesce(p_reason, ''))) < 5 then raise exception 'Give a reason'; end if;
  select * into c from affiliate_commissions where id = p_id for update;
  if not found then raise exception 'Commission not found'; end if;
  if c.status = 'void' then return 'void'; end if;
  if c.status = 'credited' then
    insert into ledger_entries (user_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
    values (c.affiliate_id, 'adjustment', -c.commission_amount, date_trunc('month', now() at time zone 'Asia/Karachi')::date,
            'commission_void', c.id::text, 'affv:' || c.id, jsonb_build_object('reason', trim(p_reason)));
  end if;
  update affiliate_commissions set status = 'void', void_reason = trim(p_reason) where id = p_id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, before, after, reason)
  values (p_staff, v_role::text, 'affiliate.void', 'affiliate_commissions', p_id::text,
          jsonb_build_object('status', c.status), jsonb_build_object('status', 'void', 'amount', c.commission_amount), trim(p_reason));
  return 'void';
end $$;

-- Staff: block/unblock an affiliate (no new commissions while blocked) or freeze/unfreeze an investor
-- (no deposits, payout changes or withdrawals while frozen).
create or replace function public.set_account_flag(p_user uuid, p_staff uuid, p_flag text, p_on boolean, p_reason text) returns text
language plpgsql security definer set search_path = public as $$
declare v_role staff_role;
begin
  select role into v_role from staff_members where user_id = p_staff and active;
  if v_role is null or v_role not in ('owner', 'compliance') then raise exception 'Only owner or compliance staff can do this'; end if;
  if p_on and length(trim(coalesce(p_reason, ''))) < 5 then raise exception 'Give a reason'; end if;
  if p_flag = 'freeze' then
    update profiles set frozen_at = case when p_on then now() end, frozen_reason = case when p_on then trim(p_reason) end where user_id = p_user;
  elsif p_flag = 'block_affiliate' then
    update profiles set affiliate_blocked_at = case when p_on then now() end where user_id = p_user;
  else raise exception 'Unknown flag'; end if;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after, reason)
  values (p_staff, v_role::text, 'account.' || p_flag || case when p_on then '' else '_off' end, 'profiles', p_user::text,
          jsonb_build_object('on', p_on), nullif(trim(coalesce(p_reason, '')), ''));
  return case when p_on then 'on' else 'off' end;
end $$;

create or replace function public.account_frozen(p_user uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select frozen_at is not null from profiles where user_id = p_user), false)
$$;

-- ------------------------------------------------------------- leaderboard
-- Computed only from credited commissions; nobody can type a name or an amount into it.
-- Shows "Affiliate #XXXX" unless the affiliate opted in to first name + last initial.
create or replace function public.affiliate_leaderboard(p_from date) returns table (
  user_id uuid, display_name text, members bigint, commission numeric, first_credit timestamptz)
language sql stable security definer set search_path = public as $$
  select c.affiliate_id,
         case when p.leaderboard_opt_in and p.full_name <> ''
              then split_part(p.full_name, ' ', 1) || ' ' || left(split_part(p.full_name, ' ', array_length(string_to_array(p.full_name, ' '), 1)), 1) || '.'
              else 'Affiliate #' || upper(left(md5(c.affiliate_id::text), 4)) end,
         (select count(*) from profiles m where m.referred_by = p.id),
         sum(c.commission_amount), min(c.credited_at)
    from affiliate_commissions c join profiles p on p.user_id = c.affiliate_id
   where c.status = 'credited' and c.ym >= p_from and p.affiliate_blocked_at is null
   group by c.affiliate_id, p.id, p.leaderboard_opt_in, p.full_name
   order by sum(c.commission_amount) desc, min(c.credited_at)
$$;

-- Everything the affiliate hub shows, for one affiliate. Members appear as first name + last initial with
-- only what they earned the affiliate; never a member's balance or deposits.
-- "pending" = deposit commissions not yet credited + an estimate of this month's fee share from the
-- month-to-date returns (credited for real only when the month closes).
create or replace function public.affiliate_summary(p_user uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_pid     uuid;
  v_code    text;
  v_opt     boolean;
  v_blocked boolean;
  v_last    date := (select max(ym) from month_closes);
  v_mtd     date := (select max(ym) from strategy_returns where status = 'mtd');
  v_fee     numeric := setting_num('affiliate_fee_share_rate', 0.15);
  v_dep     numeric := setting_num('affiliate_deposit_rate', 0);
  v_members jsonb;
  v_by      jsonb;
  v_total   numeric;
  v_wd      numeric;
begin
  select id, referral_code, leaderboard_opt_in, affiliate_blocked_at is not null
    into v_pid, v_code, v_opt, v_blocked from profiles where user_id = p_user;
  if v_pid is null then return null; end if;
  if v_last is not null and v_mtd <= v_last then v_mtd := null; end if;

  select coalesce(jsonb_agg(jsonb_build_object('n', m.name, 'ym', m.joined, 'id', m.slug, 'com', m.com, 'pending', m.pending)
                            order by m.created_at desc), '[]'::jsonb)
    into v_members
    from (
      select p.created_at,
             to_char(p.created_at at time zone 'Asia/Karachi', 'YYYY-MM') as joined,
             coalesce(nullif(initcap(split_part(trim(p.full_name), ' ', 1)), ''), 'Member')
               || coalesce(' ' || upper(substring(trim(p.full_name) from '\s(\S)\S*$')) || '.', '') as name,
             (select s.slug from holdings h join strategies s on s.id = h.strategy_id
               where h.user_id = p.user_id and exists (select 1 from ledger_entries l where l.holding_id = h.id)
               order by h.opened_at limit 1) as slug,
             coalesce((select sum(c.commission_amount) from affiliate_commissions c
                        where c.affiliate_id = p_user and c.member_id = p.user_id and c.status = 'credited'), 0) as com,
             round(coalesce((select sum(c.commission_amount) from affiliate_commissions c
                              where c.affiliate_id = p_user and c.member_id = p.user_id and c.status = 'pending'), 0)
                 + case when v_blocked or v_mtd is null then 0 else coalesce((
                     select sum(greatest(0, hv.val * r.return_pct / 100)) * 0.025 * v_fee
                       from (select h.strategy_id, sum(l.amount) as val
                               from holdings h join ledger_entries l on l.holding_id = h.id
                              where h.user_id = p.user_id and l.ym <= v_mtd group by h.strategy_id) hv
                       join strategy_returns r on r.strategy_id = hv.strategy_id and r.ym = v_mtd and r.status = 'mtd'), 0) end,
                   2) as pending
        from profiles p where p.referred_by = v_pid
    ) m;

  select coalesce(jsonb_object_agg(ym, amt), '{}'::jsonb), coalesce(sum(amt), 0) into v_by, v_total
    from (select to_char(ym, 'YYYY-MM') as ym, sum(commission_amount) as amt
            from affiliate_commissions where affiliate_id = p_user and status = 'credited' group by 1) x;
  -- affiliate money lives outside the holdings: commissions, their payouts and any voids
  select greatest(0, coalesce(sum(amount), 0)) into v_wd from ledger_entries where user_id = p_user and holding_id is null;

  return jsonb_build_object(
    'rates', jsonb_build_object('fee', v_fee, 'dep', v_dep),
    'members', v_members,
    'byMonth', v_by,
    'total', v_total,
    'pending', (select coalesce(sum((x->>'pending')::numeric), 0) from jsonb_array_elements(v_members) x),
    'withdrawable', v_wd,
    'optIn', v_opt,
    'blocked', v_blocked,
    'mtdYm', to_char(v_mtd, 'YYYY-MM'),
    'lb', jsonb_build_object(
      'month', affiliate_board(p_user, v_code, coalesce(v_last, 'infinity'::date)),
      'q',     affiliate_board(p_user, v_code, coalesce((v_last - interval '2 months')::date, 'infinity'::date)),
      'all',   affiliate_board(p_user, v_code, '2000-01-01')));
end $$;

-- Top 10 for a period, plus the caller's own row wherever they rank.
create or replace function public.affiliate_board(p_user uuid, p_code text, p_from date) returns jsonb
language sql stable security definer set search_path = public as $$
  with r as (
    select row_number() over (order by commission desc, first_credit) as rank, * from affiliate_leaderboard(p_from)
  ), top as (
    select jsonb_build_object('rank', rank, 'name', case when user_id = p_user then 'You · ' || p_code else display_name end,
                              'members', members, 'com', commission, 'you', user_id = p_user) as row, rank
      from r where rank <= 10 or user_id = p_user
  )
  select coalesce((select jsonb_agg(row order by rank) from top), '[]'::jsonb)
      || case when exists (select 1 from r where user_id = p_user) then '[]'::jsonb
              else jsonb_build_array(jsonb_build_object('rank', (select count(*) + 1 from r), 'name', 'You · ' || p_code,
                     'members', (select count(*) from profiles m join profiles a on a.id = m.referred_by where a.user_id = p_user),
                     'com', 0, 'you', true)) end
$$;

-- The signed-in investor's own summary (callable from the browser session; reads only their data).
create or replace function public.my_affiliate_summary() returns jsonb
language sql stable security definer set search_path = public as $$
  select affiliate_summary(auth.uid())
$$;

-- ---------------------------------------------------------------------- RLS
alter table public.affiliate_codes enable row level security;
alter table public.affiliate_commissions enable row level security;
drop policy if exists affiliate_codes_own on public.affiliate_codes;
create policy affiliate_codes_own on public.affiliate_codes for select to authenticated using (user_id = auth.uid());
drop policy if exists affiliate_commissions_own on public.affiliate_commissions;
create policy affiliate_commissions_own on public.affiliate_commissions for select to authenticated using (affiliate_id = auth.uid());
revoke insert, update, delete on public.affiliate_codes, public.affiliate_commissions from anon, authenticated;

do $$ declare f text; begin
  foreach f in array array['setting_num(text,numeric)', 'set_referral_code(uuid,text)', 'commission_affiliate(uuid)', 'same_person(uuid,uuid)',
    'credit_commission(uuid)', 'affiliate_on_fee(uuid,uuid,date,numeric)', 'affiliate_on_deposit(uuid,date)', 'affiliate_settle_deposits(date)',
    'void_commission(uuid,uuid,text)', 'set_account_flag(uuid,uuid,text,boolean,text)', 'account_frozen(uuid)', 'affiliate_leaderboard(date)',
    'affiliate_summary(uuid)', 'affiliate_board(uuid,text,date)'] loop
    execute format('revoke execute on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to service_role', f);
  end loop;
end $$;
revoke execute on function public.my_affiliate_summary() from public, anon;
grant execute on function public.my_affiliate_summary() to authenticated, service_role;


-- ======================================================== 0009_admin.sql
-- Capital 50 AI — Phase 7: staff admin panel (PRODUCTION-BRIEF §6, §7). Safe to re-run.
-- Every staff action goes through a function here that checks the role and writes the audit log.

-- The role of an active staff member, or null.
create or replace function public.staff_role_of(p_staff uuid) returns staff_role
language sql stable security definer set search_path = public as $$
  select role from staff_members where user_id = p_staff and active
$$;

create or replace function public.require_staff(p_staff uuid, p_roles staff_role[]) returns staff_role
language plpgsql stable security definer set search_path = public as $$
declare v staff_role := staff_role_of(p_staff);
begin
  if v is null or not (v = any (p_roles)) then
    raise exception 'Your role can''t do this (needs %)', array_to_string(p_roles, ' or ');
  end if;
  return v;
end $$;

-- ------------------------------------------------------------------ returns
-- Owner/compliance enter a month's figure as a draft or month-to-date estimate; only the owner
-- publishes. A closed month can never change: its money has already been booked.
create or replace function public.set_strategy_return(p_staff uuid, p_slug text, p_ym date, p_pct numeric, p_status return_status, p_note text)
returns text
language plpgsql security definer set search_path = public as $$
declare
  v_role staff_role := require_staff(p_staff, case when p_status = 'published' then array['owner']::staff_role[]
                                                    else array['owner', 'compliance']::staff_role[] end);
  v_sid  uuid;
  v_old  strategy_returns%rowtype;
  v_last date := (select max(ym) from month_closes);
begin
  if p_ym is null or extract(day from p_ym) <> 1 then raise exception 'Pick a month'; end if;
  if p_pct is null or p_pct < -100 or p_pct > 1000 then raise exception 'Enter a return between -100%% and 1000%%'; end if;
  if length(trim(coalesce(p_note, ''))) < 5 then raise exception 'Add a source note (where this figure comes from)'; end if;
  if v_last is not null and p_ym <= v_last then
    raise exception '% is already closed; its return can''t change', to_char(p_ym, 'Mon YYYY');
  end if;
  if p_ym > date_trunc('month', now() at time zone 'Asia/Karachi')::date then raise exception 'That month hasn''t started'; end if;
  if p_status = 'published' and p_ym >= date_trunc('month', now() at time zone 'Asia/Karachi')::date then
    raise exception 'A month can only be published after it ends; use month-to-date until then';
  end if;
  select id into v_sid from strategies where slug = p_slug;
  if v_sid is null then raise exception 'Unknown strategy'; end if;

  select * into v_old from strategy_returns where strategy_id = v_sid and ym = p_ym for update;
  insert into strategy_returns (strategy_id, ym, return_pct, status, source_note, published_at, published_by)
  values (v_sid, p_ym, round(p_pct, 3), p_status, trim(p_note),
          case when p_status = 'published' then now() end, case when p_status = 'published' then p_staff end)
  on conflict (strategy_id, ym) do update
     set return_pct = excluded.return_pct, status = excluded.status, source_note = excluded.source_note,
         published_at = excluded.published_at, published_by = excluded.published_by;

  insert into audit_log (actor_id, actor_role, action, entity, entity_id, before, after, reason)
  values (p_staff, v_role::text, 'returns.' || p_status, 'strategy_returns', p_slug || ':' || to_char(p_ym, 'YYYY-MM'),
          case when v_old.id is not null then jsonb_build_object('pct', v_old.return_pct, 'status', v_old.status) end,
          jsonb_build_object('pct', round(p_pct, 3), 'status', p_status), trim(p_note));
  return p_status::text;
end $$;

-- What close_month(p_ym) would book, without booking anything.
create or replace function public.preview_month_close(p_ym date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_last  date := (select max(ym) from month_closes);
  v_rows  jsonb;
  v_block text;
begin
  with hv as (
    select h.strategy_id, h.id,
           (select coalesce(sum(amount), 0) from ledger_entries l
             where l.holding_id = h.id and (l.ym < p_ym or (l.ym = p_ym and l.type in ('deposit', 'withdrawal')))) as v
      from holdings h
  ), s as (
    select st.slug, st.name, st.sort_order, count(hv.id) filter (where hv.v > 0) as holdings,
           coalesce(sum(hv.v) filter (where hv.v > 0), 0) as value_start,
           r.return_pct, r.status,
           coalesce(sum(round(hv.v * r.return_pct / 100, 2)) filter (where hv.v > 0), 0) as profit,
           coalesce(sum(round(greatest(round(hv.v * r.return_pct / 100, 2), 0) * 0.025, 2)) filter (where hv.v > 0), 0) as fees
      from strategies st
      left join hv on hv.strategy_id = st.id
      left join strategy_returns r on r.strategy_id = st.id and r.ym = p_ym
     group by st.slug, st.name, st.sort_order, r.return_pct, r.status
  )
  select jsonb_agg(jsonb_build_object('slug', slug, 'name', name, 'holdings', holdings, 'value_start', value_start,
                                      'r', return_pct, 'status', status,
                                      'profit', case when return_pct is null then null else profit end,
                                      'fees', case when return_pct is null then null else fees end) order by sort_order)
    into v_rows from s;

  v_block := case
    when exists (select 1 from month_closes where ym = p_ym) then 'Already closed'
    when v_last is not null and p_ym <> (v_last + interval '1 month')::date then 'Close ' || to_char(v_last + interval '1 month', 'Mon YYYY') || ' first'
    when p_ym >= date_trunc('month', now() at time zone 'Asia/Karachi')::date then 'The month has not ended yet'
    when exists (select 1 from jsonb_array_elements(v_rows) x where (x->>'holdings')::int > 0 and coalesce(x->>'status', '') <> 'published')
      then 'Publish every strategy that has investors first'
  end;
  return jsonb_build_object('ym', to_char(p_ym, 'YYYY-MM'), 'rows', v_rows, 'can_close', v_block is null, 'blocked', v_block);
end $$;

-- Staff wrapper so the close is attributed and owner-only.
create or replace function public.staff_close_month(p_staff uuid, p_ym date) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  perform require_staff(p_staff, array['owner']::staff_role[]);
  return close_month(p_ym, p_staff);
end $$;

-- ------------------------------------------------------------------ tickets
do $$ begin
  create type public.ticket_status as enum ('open', 'answered', 'closed');
exception when duplicate_object then null; end $$;

create table if not exists public.tickets (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users(id) on delete restrict,
  ref             text not null unique,
  category        text not null check (category in ('Deposit', 'Withdrawal', 'Verification (KYC)', 'Affiliate', 'Account', 'Account closure', 'Other')),
  subject         text not null check (length(subject) between 3 and 80),
  status          public.ticket_status not null default 'open',
  assigned_to     uuid references auth.users(id),
  last_message_at timestamptz not null default now(),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index if not exists tickets_user on public.tickets (user_id, created_at desc);
create index if not exists tickets_queue on public.tickets (status, last_message_at);
drop trigger if exists tickets_updated on public.tickets;
create trigger tickets_updated before update on public.tickets for each row execute function public.set_updated_at();

create table if not exists public.ticket_messages (
  id         uuid primary key default gen_random_uuid(),
  ticket_id  uuid not null references public.tickets(id) on delete cascade,
  author_id  uuid not null references auth.users(id),
  from_staff boolean not null,
  body       text not null check (length(body) between 1 and 1500),
  created_at timestamptz not null default now()
);
create index if not exists ticket_messages_ticket on public.ticket_messages (ticket_id, created_at);
-- Append-only, like the ledger: only the owner's demo/test purge (transaction-local flag) can delete.
create or replace function public.append_only_unless_purge() returns trigger
language plpgsql as $$
begin
  if tg_op = 'DELETE' and current_setting('c50.ledger_purge', true) = 'on' then return old; end if;
  raise exception '% is append-only', tg_table_name;
end $$;

drop trigger if exists ticket_messages_no_change on public.ticket_messages;
create trigger ticket_messages_no_change before update or delete on public.ticket_messages
  for each row execute function public.append_only_unless_purge();
drop trigger if exists payment_events_no_change on public.payment_events;
create trigger payment_events_no_change before update or delete on public.payment_events
  for each row execute function public.append_only_unless_purge();

create or replace function public.open_ticket(p_user uuid, p_category text, p_subject text, p_body text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_ref text;
begin
  if p_category is null or p_category not in ('Deposit', 'Withdrawal', 'Verification (KYC)', 'Affiliate', 'Account', 'Account closure', 'Other') then
    raise exception 'Choose a category';
  end if;
  if length(trim(coalesce(p_subject, ''))) not between 3 and 80 then raise exception 'Write a subject (3 to 80 characters)'; end if;
  if length(trim(coalesce(p_body, ''))) not between 1 and 1500 then raise exception 'Write your message (up to 1,500 characters)'; end if;
  if (select count(*) from tickets where user_id = p_user and status <> 'closed') >= 5 then
    raise exception 'You have 5 open tickets. Please wait for a reply or close one first.';
  end if;
  loop
    v_ref := 'T-' || upper(substr(md5(gen_random_uuid()::text), 1, 6));
    exit when not exists (select 1 from tickets where ref = v_ref);
  end loop;
  insert into tickets (user_id, ref, category, subject) values (p_user, v_ref, p_category, trim(p_subject)) returning id into v_id;
  insert into ticket_messages (ticket_id, author_id, from_staff, body) values (v_id, p_user, false, trim(p_body));
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_user, 'investor', 'ticket.open', 'tickets', v_id::text, jsonb_build_object('ref', v_ref, 'category', p_category));
  return jsonb_build_object('id', v_id, 'ref', v_ref);
end $$;

-- A reply from the investor (p_staff false) or from staff. Staff replies mark it answered.
create or replace function public.ticket_reply(p_ticket uuid, p_author uuid, p_staff boolean, p_body text) returns text
language plpgsql security definer set search_path = public as $$
declare t tickets%rowtype; v_role staff_role;
begin
  select * into t from tickets where id = p_ticket for update;
  if not found then raise exception 'Ticket not found'; end if;
  if p_staff then
    v_role := require_staff(p_author, array['owner', 'compliance', 'finance', 'support']::staff_role[]);
  elsif t.user_id <> p_author then
    raise exception 'Ticket not found';
  end if;
  if length(trim(coalesce(p_body, ''))) = 0 then raise exception 'Write a message'; end if;
  insert into ticket_messages (ticket_id, author_id, from_staff, body) values (t.id, p_author, p_staff, trim(p_body));
  update tickets set status = case when p_staff then 'answered' else 'open' end::ticket_status, last_message_at = now(),
         assigned_to = case when p_staff then coalesce(assigned_to, p_author) else assigned_to end
   where id = t.id;
  if p_staff then
    insert into audit_log (actor_id, actor_role, action, entity, entity_id) values (p_author, v_role::text, 'ticket.reply', 'tickets', t.id::text);
  end if;
  return case when p_staff then 'answered' else 'open' end;
end $$;

create or replace function public.ticket_close(p_ticket uuid, p_actor uuid, p_staff boolean) returns text
language plpgsql security definer set search_path = public as $$
declare t tickets%rowtype; v_role staff_role;
begin
  select * into t from tickets where id = p_ticket for update;
  if not found or (not p_staff and t.user_id <> p_actor) then raise exception 'Ticket not found'; end if;
  if p_staff then v_role := require_staff(p_actor, array['owner', 'compliance', 'finance', 'support']::staff_role[]); end if;
  update tickets set status = 'closed' where id = t.id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id)
  values (p_actor, coalesce(v_role::text, 'investor'), 'ticket.close', 'tickets', t.id::text);
  return 'closed';
end $$;

-- ------------------------------------------------------------------ nominee
-- One nominee per investor. The CNIC is encrypted by the server (C50_DATA_KEY); only a hint is shown.
create table if not exists public.nominees (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  full_name  text not null check (length(full_name) between 3 and 80),
  relation   text not null check (relation in ('Spouse', 'Father', 'Mother', 'Son', 'Daughter', 'Brother', 'Sister', 'Other')),
  cnic_enc   text not null,
  cnic_hint  text not null,
  phone      text,
  updated_at timestamptz not null default now()
);

-- The signed-in investor's nominee, without the encrypted CNIC.
create or replace function public.my_nominee() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('name', full_name, 'rel', relation, 'hint', cnic_hint) from nominees where user_id = auth.uid()
$$;
revoke execute on function public.my_nominee() from public, anon;
grant execute on function public.my_nominee() to authenticated, service_role;

-- ------------------------------------------------------------- launch reset
-- Removes one account and everything it owns (money rows, identity records, tickets). Used for the
-- demo account and test accounts before launch. Returns the KYC file paths so the server can delete
-- the files through the Storage API (Supabase doesn't allow deleting them from SQL).
-- The audit log keeps its history.
create or replace function public.purge_user_data(p_uid uuid) returns text[]
language plpgsql security definer set search_path = public as $$
declare v_files text[];
begin
  select coalesce(array_agg(storage_path), '{}') into v_files from kyc_documents where user_id = p_uid;
  perform set_config('c50.ledger_purge', 'on', true);
  -- take this account's share out of the month totals so the books still reconcile
  update month_closes mc
     set total_profit = mc.total_profit - x.pl, total_fees = mc.total_fees - x.fee, holdings = greatest(0, mc.holdings - x.h)
    from (select ref_id, coalesce(sum(amount) filter (where type in ('profit', 'loss')), 0) as pl,
                 coalesce(-sum(amount) filter (where type = 'fee'), 0) as fee, count(distinct holding_id) as h
            from ledger_entries where user_id = p_uid and ref_type = 'month_close' group by ref_id) x
   where to_char(mc.ym, 'YYYY-MM') = x.ref_id;
  delete from affiliate_commissions where affiliate_id = p_uid or member_id = p_uid;
  delete from ledger_entries where user_id = p_uid;
  delete from withdrawals where user_id = p_uid;
  delete from payout_methods where user_id = p_uid;
  delete from payment_events where deposit_id in (select id from deposits where user_id = p_uid);
  delete from deposits where user_id = p_uid;
  delete from kyc_documents where user_id = p_uid;
  delete from kyc_applications where user_id = p_uid;
  delete from tickets where user_id = p_uid;
  delete from holdings where user_id = p_uid;
  delete from auth.users where id = p_uid;
  perform set_config('c50.ledger_purge', 'off', true);
  return v_files;
end $$;

create or replace function public.purge_demo_data() returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid;
begin
  select id into v_uid from auth.users where phone = '923001234567';
  if v_uid is null then return; end if;
  perform purge_user_data(v_uid);
  insert into audit_log (actor_role, action, entity, entity_id, reason)
  values ('system', 'demo.purge', 'auth.users', v_uid::text, 'Demo account and sample money removed');
end $$;

-- Owner, before launch: removes the demo account, then all test money. Refuses if a single live-mode
-- deposit exists, so it can never touch real money. Investor accounts, identity checks and payout
-- methods stay; closed months stay closed (their totals are zeroed to match the empty ledger).
create or replace function public.prepare_for_launch(p_staff uuid, p_confirm text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_demo  uuid := (select id from auth.users where phone = '923001234567');
  v_files text[] := '{}';
  v       jsonb;
begin
  perform require_staff(p_staff, array['owner']::staff_role[]);
  if p_confirm is distinct from 'RESET TEST MONEY' then raise exception 'Type RESET TEST MONEY to confirm'; end if;
  if exists (select 1 from deposits where mode = 'live') then
    raise exception 'Real (live-mode) deposits exist, so nothing was reset';
  end if;
  if v_demo is not null then v_files := purge_user_data(v_demo); end if;
  v := jsonb_build_object('demo_removed', v_demo is not null,
         'ledger_rows', (select count(*) from ledger_entries), 'withdrawals', (select count(*) from withdrawals),
         'deposits', (select count(*) from deposits where status in ('paid', 'pending')),
         'commissions', (select count(*) from affiliate_commissions));
  perform set_config('c50.ledger_purge', 'on', true);
  delete from affiliate_commissions;
  delete from ledger_entries;
  delete from withdrawals;
  delete from notifications where kind in ('deposit', 'withdrawal', 'affiliate', 'month');
  update deposits set status = case when status = 'paid' then 'refunded' else 'expired' end::deposit_status,
         status_note = 'Test money removed before launch'
   where status in ('paid', 'pending');
  update month_closes set holdings = 0, total_profit = 0, total_fees = 0;
  delete from holdings h where not exists (select 1 from ledger_entries l where l.holding_id = h.id);
  perform set_config('c50.ledger_purge', 'off', true);
  insert into audit_log (actor_id, actor_role, action, entity, reason, after)
  values (p_staff, 'owner', 'launch.reset', 'ledger_entries', 'Test money removed before launch', v);
  return v || jsonb_build_object('files', to_jsonb(v_files));
end $$;

-- ------------------------------------------------------------------ settings
-- Owner-only. Each setting is range-checked here so a typo can't set a 500% commission.
create or replace function public.set_setting(p_staff uuid, p_key text, p_value jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_role staff_role := require_staff(p_staff, array['owner']::staff_role[]);
  v_old  jsonb;
  v_num  numeric;
begin
  if p_key in ('affiliate_fee_share_rate', 'affiliate_deposit_rate', 'withdrawal_two_approvals_above') then
    begin v_num := (p_value #>> '{}')::numeric; exception when others then raise exception 'Enter a number'; end;
    if v_num is null then raise exception 'Enter a number'; end if;
    if p_key = 'affiliate_fee_share_rate' and (v_num < 0 or v_num > 1) then raise exception 'Fee share must be between 0%% and 100%% of the fee'; end if;
    if p_key = 'affiliate_deposit_rate' and (v_num < 0 or v_num > 0.10) then raise exception 'Deposit commission must be between 0%% and 10%%'; end if;
    if p_key = 'withdrawal_two_approvals_above' and (v_num < 0 or v_num > 100000000) then raise exception 'Enter an amount in rupees'; end if;
    p_value := to_jsonb(v_num);
  elsif p_key = 'bank_account' then
    if jsonb_typeof(p_value) <> 'object' or coalesce(p_value->>'bank', '') = '' or coalesce(p_value->>'title', '') = ''
       or upper(replace(coalesce(p_value->>'iban', ''), ' ', '')) !~ '^PK[0-9]{2}[A-Z]{4}[0-9A-Z]{16}$' then
      raise exception 'Enter the bank, account title and a PK IBAN (24 characters)';
    end if;
    p_value := jsonb_build_object('bank', trim(p_value->>'bank'), 'title', trim(p_value->>'title'),
                                  'iban', upper(replace(p_value->>'iban', ' ', '')));
  else
    raise exception 'Unknown setting %', p_key;
  end if;
  select value into v_old from app_settings where key = p_key;
  insert into app_settings (key, value, updated_at) values (p_key, p_value, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, before, after)
  values (p_staff, v_role::text, 'settings.set', 'app_settings', p_key, v_old, p_value);
  return p_value;
end $$;

-- ------------------------------------------------------------------ staff
create or replace function public.staff_grant(p_owner uuid, p_email text, p_role staff_role) returns text
language plpgsql security definer set search_path = public as $$
declare v_uid uuid; v_old staff_members%rowtype;
begin
  perform require_staff(p_owner, array['owner']::staff_role[]);
  select id into v_uid from auth.users where lower(email) = lower(trim(p_email));
  if v_uid is null then raise exception 'No login with email %. Create it first in Supabase: Authentication > Users > Add user.', trim(p_email); end if;
  if v_uid = p_owner then raise exception 'You can''t change your own role'; end if;
  select * into v_old from staff_members where user_id = v_uid;
  insert into staff_members (user_id, role, active) values (v_uid, p_role, true)
  on conflict (user_id) do update set role = excluded.role, active = true;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, before, after)
  values (p_owner, 'owner', 'staff.grant', 'staff_members', v_uid::text,
          case when v_old.user_id is not null then jsonb_build_object('role', v_old.role, 'active', v_old.active) end,
          jsonb_build_object('email', lower(trim(p_email)), 'role', p_role));
  return format('%s is now %s staff. They sign in at /admin/login and set up an authenticator.', lower(trim(p_email)), p_role);
end $$;

create or replace function public.staff_revoke(p_owner uuid, p_user uuid) returns text
language plpgsql security definer set search_path = public as $$
begin
  perform require_staff(p_owner, array['owner']::staff_role[]);
  if p_user = p_owner then raise exception 'You can''t remove yourself'; end if;
  update staff_members set active = false where user_id = p_user and active;
  if not found then raise exception 'Not active staff'; end if;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_owner, 'owner', 'staff.revoke', 'staff_members', p_user::text, jsonb_build_object('active', false));
  return 'revoked';
end $$;

-- ------------------------------------------------------------- reconciliation
-- Runs daily (Vercel cron) and on demand. Every check compares two independent records of the same money.
create table if not exists public.reconciliation_runs (
  id      uuid primary key default gen_random_uuid(),
  ran_at  timestamptz not null default clock_timestamp(),
  ok      boolean not null,
  checks  jsonb not null,
  trigger text not null default 'cron'
);
create index if not exists reconciliation_runs_at on public.reconciliation_runs (ran_at desc);

create or replace function public.run_reconciliation(p_trigger text default 'cron') returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  c   jsonb := '[]'::jsonb;
  n   numeric;
  m   numeric;
  k   bigint;
  v_ok boolean;
begin
  -- 1. every paid deposit has exactly its ledger entry, and nothing else is booked as a deposit
  select coalesce(sum(amount), 0) into n from deposits where status = 'paid';
  select coalesce(sum(amount), 0) into m from ledger_entries where type = 'deposit' and ref_type = 'deposit';
  select count(*) into k from deposits d where status = 'paid'
     and not exists (select 1 from ledger_entries l where l.idempotency_key = 'dep:' || d.id and l.amount = d.amount);
  c := c || jsonb_build_object('name', 'Deposits match the ledger', 'ok', n = m and k = 0,
             'detail', format('paid deposits Rs %s, ledger Rs %s, missing %s', n, m, k));

  -- 2. paid withdrawals = what left the ledger for them (holdings + affiliate part)
  select coalesce(sum(amount), 0) into n from withdrawals where status = 'paid';
  select coalesce(-sum(amount), 0) into m from ledger_entries where ref_type = 'withdrawal' and type in ('withdrawal', 'affiliate_payout');
  select count(*) into k from withdrawals w where status = 'paid'
     and (select coalesce(-sum(amount), 0) from ledger_entries l where l.ref_type = 'withdrawal' and l.ref_id = w.id::text) <> w.amount;
  c := c || jsonb_build_object('name', 'Withdrawals match the ledger', 'ok', n = m and k = 0,
             'detail', format('paid Rs %s, ledger Rs %s, mismatched %s', n, m, k));

  -- 3. credited commissions are in the ledger once; voided-after-credit ones are reversed
  select count(*) into k from affiliate_commissions a
   where (a.status = 'credited' and not exists (select 1 from ledger_entries l where l.idempotency_key = 'affc:' || a.id and l.amount = a.commission_amount))
      or (a.status = 'void' and exists (select 1 from ledger_entries l where l.idempotency_key = 'affc:' || a.id)
                            and not exists (select 1 from ledger_entries l where l.idempotency_key = 'affv:' || a.id and l.amount = -a.commission_amount))
      or (a.status = 'pending' and exists (select 1 from ledger_entries l where l.idempotency_key = 'affc:' || a.id));
  c := c || jsonb_build_object('name', 'Affiliate commissions match the ledger', 'ok', k = 0, 'detail', format('%s mismatched', k));

  -- 4. each month close total = its ledger entries; each fee = 2.5% of that holding's profit
  select count(*) into k from month_closes mc
   where mc.total_profit <> (select coalesce(sum(amount), 0) from ledger_entries where ref_type = 'month_close' and ref_id = to_char(mc.ym, 'YYYY-MM') and type in ('profit', 'loss'))
      or mc.total_fees <> (select coalesce(-sum(amount), 0) from ledger_entries where ref_type = 'month_close' and ref_id = to_char(mc.ym, 'YYYY-MM') and type = 'fee');
  c := c || jsonb_build_object('name', 'Month closes match the ledger', 'ok', k = 0, 'detail', format('%s months mismatched', k));
  select count(*) into k from ledger_entries f
   where f.type = 'fee' and f.ref_type = 'month_close'
     and -f.amount <> (select round(greatest(coalesce(sum(p.amount), 0), 0) * 0.025, 2) from ledger_entries p
                        where p.holding_id = f.holding_id and p.ref_type = 'month_close' and p.ref_id = f.ref_id and p.type = 'profit');
  c := c || jsonb_build_object('name', 'Every fee is 2.5% of profit', 'ok', k = 0, 'detail', format('%s fees off', k));

  -- 5. no negative balances, and money in review never exceeds the balance
  select count(*) into k from (select holding_id from ledger_entries where holding_id is not null group by holding_id having sum(amount) < 0) x;
  c := c || jsonb_build_object('name', 'No negative holdings', 'ok', k = 0, 'detail', format('%s negative', k));
  select count(*) into k from (
    select w.user_id from withdrawals w where w.status in ('requested', 'approved') group by w.user_id
    having sum(w.amount) > (select coalesce(sum(amount), 0) from ledger_entries l where l.user_id = w.user_id)) x;
  c := c || jsonb_build_object('name', 'Withdrawals in review are covered', 'ok', k = 0, 'detail', format('%s investors over', k));

  -- 6. deposits stuck: paid at the provider but still pending here for over a day (needs a look)
  select count(*) into k from deposits where status = 'pending' and method <> 'bank' and created_at < now() - interval '1 day'
     and exists (select 1 from payment_events e where e.deposit_id = deposits.id and e.signature_ok);
  c := c || jsonb_build_object('name', 'No paid-but-pending deposits', 'ok', k = 0, 'detail', format('%s to check', k));

  select bool_and((x->>'ok')::boolean) into v_ok from jsonb_array_elements(c) x;
  insert into reconciliation_runs (ok, checks, trigger) values (v_ok, c, left(coalesce(p_trigger, 'cron'), 20));
  if not v_ok then
    insert into audit_log (actor_role, action, entity, reason, after)
    values ('system', 'reconcile.fail', 'reconciliation_runs', 'Daily reconciliation found a mismatch', c);
  end if;
  return jsonb_build_object('ok', v_ok, 'checks', c);
end $$;

-- ------------------------------------------------------------------ overview
create or replace function public.admin_overview() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'investors',        (select count(*) from profiles p where not exists (select 1 from staff_members s where s.user_id = p.user_id)),
    'verified',         (select count(distinct user_id) from kyc_applications where status = 'verified'),
    'invested',         (select coalesce(sum(amount), 0) from ledger_entries where holding_id is not null),
    'affiliate_owed',   (select coalesce(sum(amount), 0) from ledger_entries where holding_id is null),
    'deposits_month',   (select coalesce(sum(amount), 0) from deposits where status = 'paid'
                          and paid_at >= date_trunc('month', now() at time zone 'Asia/Karachi') at time zone 'Asia/Karachi'),
    'paid_out_month',   (select coalesce(sum(amount), 0) from withdrawals where status = 'paid'
                          and paid_at >= date_trunc('month', now() at time zone 'Asia/Karachi') at time zone 'Asia/Karachi'),
    'kyc_review',       (select count(*) from kyc_applications where status = 'review'),
    'bank_pending',     (select count(*) from deposits where status = 'pending' and method = 'bank'),
    'wd_open',          (select count(*) from withdrawals where status in ('requested', 'approved')),
    'wd_open_amount',   (select coalesce(sum(amount), 0) from withdrawals where status in ('requested', 'approved')),
    'tickets_open',     (select count(*) from tickets where status = 'open'),
    'frozen',           (select count(*) from profiles where frozen_at is not null),
    'last_close',       (select to_char(max(ym), 'YYYY-MM') from month_closes),
    'fees_total',       (select coalesce(-sum(amount), 0) from ledger_entries where type = 'fee'),
    'commission_total', (select coalesce(sum(commission_amount), 0) from affiliate_commissions where status = 'credited'),
    'reconcile',        (select jsonb_build_object('ok', ok, 'at', ran_at, 'checks', checks, 'stale', ran_at < now() - interval '36 hours')
                           from reconciliation_runs order by ran_at desc limit 1),
    'demo_present',     exists (select 1 from auth.users where phone = '923001234567'))
$$;

-- Staff search: name, mobile (any format), email or invite code. Staff accounts aren't listed.
create or replace function public.admin_users(p_q text, p_filter text default null, p_limit int default 50) returns table (
  user_id uuid, full_name text, phone text, email text, referral_code text, created_at timestamptz,
  kyc text, balance numeric, members bigint, frozen boolean, affiliate_blocked boolean)
language sql stable security definer set search_path = public as $$
  with q as (select nullif(trim(coalesce(p_q, '')), '') as t,
                    nullif(regexp_replace(coalesce(p_q, ''), '[^0-9]', '', 'g'), '') as d)
  select p.user_id, p.full_name, p.phone, p.email, p.referral_code, p.created_at,
         coalesce((select k.status::text from kyc_applications k where k.user_id = p.user_id order by k.created_at desc limit 1), 'none'),
         coalesce((select sum(amount) from ledger_entries l where l.user_id = p.user_id), 0),
         (select count(*) from profiles m where m.referred_by = p.id),
         p.frozen_at is not null, p.affiliate_blocked_at is not null
    from profiles p, q
   where not exists (select 1 from staff_members s where s.user_id = p.user_id)
     and (q.t is null
          or p.full_name ilike '%' || q.t || '%' or p.email ilike '%' || q.t || '%' or p.referral_code = upper(q.t)
          or (length(q.d) >= 4 and p.phone like '%' || right(q.d, 10) || '%'))
     and (p_filter is null or (p_filter = 'frozen' and p.frozen_at is not null) or (p_filter = 'blocked' and p.affiliate_blocked_at is not null))
   order by p.created_at desc
   limit least(greatest(coalesce(p_limit, 50), 1), 200)
$$;

-- ---------------------------------------------------------------------- RLS
alter table public.tickets             enable row level security;
alter table public.ticket_messages     enable row level security;
alter table public.nominees            enable row level security;
alter table public.reconciliation_runs enable row level security;

drop policy if exists tickets_own on public.tickets;
create policy tickets_own on public.tickets for select to authenticated using (user_id = auth.uid());
drop policy if exists ticket_messages_own on public.ticket_messages;
create policy ticket_messages_own on public.ticket_messages for select to authenticated
  using (exists (select 1 from public.tickets t where t.id = ticket_id and t.user_id = auth.uid()));
revoke insert, update, delete on public.tickets, public.ticket_messages from anon, authenticated;
revoke all on public.nominees, public.reconciliation_runs from anon, authenticated;

do $$ declare f text; begin
  foreach f in array array['staff_role_of(uuid)', 'require_staff(uuid,staff_role[])',
    'set_strategy_return(uuid,text,date,numeric,return_status,text)', 'preview_month_close(date)', 'staff_close_month(uuid,date)',
    'open_ticket(uuid,text,text,text)', 'ticket_reply(uuid,uuid,boolean,text)', 'ticket_close(uuid,uuid,boolean)',
    'set_setting(uuid,text,jsonb)', 'staff_grant(uuid,text,staff_role)', 'staff_revoke(uuid,uuid)',
    'run_reconciliation(text)', 'admin_overview()', 'admin_users(text,text,int)',
    'purge_user_data(uuid)', 'purge_demo_data()', 'prepare_for_launch(uuid,text)'] loop
    execute format('revoke execute on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to service_role', f);
  end loop;
end $$;


-- ======================================================== 0010_hardening.sql
-- Capital 50 AI — Phase 7 hardening: trusted devices, notifications from real events. Safe to re-run.

-- ------------------------------------------------------------- trusted devices
-- A browser that passed an SMS code once. Logging in from any other browser asks for a code.
-- Only a hash of the device cookie is stored.
create table if not exists public.trusted_devices (
  user_id      uuid not null references auth.users(id) on delete cascade,
  device_hash  text not null,
  label        text,
  created_at   timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  primary key (user_id, device_hash)
);
alter table public.trusted_devices enable row level security;
revoke all on public.trusted_devices from anon, authenticated;

-- ------------------------------------------------------------- notifications
-- Written by triggers when something happens to an investor's money or account, so nothing can be
-- missed or invented. In-app now; sms_sent_at / email_sent_at are there for the SMS and email sender.
create table if not exists public.notifications (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete cascade,
  kind          text not null,            -- deposit | withdrawal | kyc | affiliate | month | support
  icon          text not null,
  title         text not null,
  body          text not null default '',
  link          text not null default '#overview',
  dedupe_key    text unique,
  created_at    timestamptz not null default clock_timestamp(),
  read_at       timestamptz,
  sms_sent_at   timestamptz,
  email_sent_at timestamptz
);
create index if not exists notifications_user on public.notifications (user_id, created_at desc);

alter table public.notifications enable row level security;
drop policy if exists notifications_own on public.notifications;
create policy notifications_own on public.notifications for select to authenticated using (user_id = auth.uid());
revoke insert, update, delete on public.notifications from anon, authenticated;

create or replace function public.notify(p_user uuid, p_kind text, p_icon text, p_title text, p_body text, p_link text, p_key text)
returns void language sql security definer set search_path = public as $$
  insert into notifications (user_id, kind, icon, title, body, link, dedupe_key)
  values (p_user, p_kind, p_icon, p_title, coalesce(p_body, ''), p_link, p_key)
  on conflict (dedupe_key) do nothing
$$;

create or replace function public.rs_text(n numeric) returns text language sql immutable as $$
  select 'Rs ' || regexp_replace(to_char(n, 'FM999,999,999,990.00'), '\.00$', '')
$$;

-- deposits: credited / failed / expired
create or replace function public.notify_deposit() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status is distinct from old.status then
    if new.status = 'paid' then
      perform notify(new.user_id, 'deposit', 'circle-check', 'Deposit received',
        format('%s added. It starts earning in %s.', rs_text(new.amount), to_char(new.effective_ym, 'FMMonth YYYY')),
        '#wallet', 'dep:' || new.id || ':paid');
    elsif new.status in ('failed', 'expired') then
      perform notify(new.user_id, 'deposit', 'x', 'Deposit not completed',
        format('%s (%s): nothing was charged to your balance.', rs_text(new.amount), new.reference), '#wallet', 'dep:' || new.id || ':' || new.status);
    end if;
  end if;
  return new;
end $$;
drop trigger if exists deposits_notify on public.deposits;
create trigger deposits_notify after update on public.deposits for each row execute function public.notify_deposit();

-- withdrawals: approved / paid / rejected
create or replace function public.notify_withdrawal() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status is distinct from old.status then
    if new.status = 'approved' then
      perform notify(new.user_id, 'withdrawal', 'check', 'Withdrawal approved', format('%s is being sent to your account.', rs_text(new.amount)), '#wallet', 'wd:' || new.id || ':approved');
    elsif new.status = 'paid' then
      perform notify(new.user_id, 'withdrawal', 'banknote', 'Withdrawal sent', format('%s sent. Reference %s.', rs_text(new.amount), coalesce(new.tx_ref, '')), '#wallet', 'wd:' || new.id || ':paid');
    elsif new.status = 'rejected' then
      perform notify(new.user_id, 'withdrawal', 'x', 'Withdrawal not approved', format('%s: %s', rs_text(new.amount), coalesce(new.reason, '')), '#wallet', 'wd:' || new.id || ':rejected');
    end if;
  end if;
  return new;
end $$;
drop trigger if exists withdrawals_notify on public.withdrawals;
create trigger withdrawals_notify after update on public.withdrawals for each row execute function public.notify_withdrawal();

-- identity check decided
create or replace function public.notify_kyc() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status is distinct from old.status then
    if new.status = 'verified' then
      perform notify(new.user_id, 'kyc', 'badge-check', 'Identity verified', 'You can now add payout methods and withdraw.', '#kyc', 'kyc:' || new.id || ':verified');
    elsif new.status = 'rejected' then
      perform notify(new.user_id, 'kyc', 'shield-alert', 'Identity check not approved', coalesce(new.rejection_reason, 'Please check your details and try again.'), '#kyc', 'kyc:' || new.id || ':rejected');
    end if;
  end if;
  return new;
end $$;
drop trigger if exists kyc_notify on public.kyc_applications;
create trigger kyc_notify after update on public.kyc_applications for each row execute function public.notify_kyc();

-- affiliate commission credited
create or replace function public.notify_commission() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'credited' and old.status is distinct from 'credited' then
    perform notify(new.affiliate_id, 'affiliate', 'gift', 'Affiliate commission credited',
      format('%s from a member''s %s %s.', rs_text(new.commission_amount), case when new.kind = 'deposit' then 'deposit in' else 'fee for' end, to_char(new.ym, 'FMMonth YYYY')),
      '#affiliate', 'affc:' || new.id);
  end if;
  return new;
end $$;
drop trigger if exists commissions_notify on public.affiliate_commissions;
create trigger commissions_notify after update on public.affiliate_commissions for each row execute function public.notify_commission();

-- a new member signed up with your code
create or replace function public.notify_member() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.referred_by is not null then
    perform notify((select user_id from profiles where id = new.referred_by), 'affiliate', 'users', 'New member joined with your link',
      coalesce(nullif(initcap(split_part(trim(new.full_name), ' ', 1)), ''), 'A new member') || ' · not invested yet', '#affiliate', 'member:' || new.id);
  end if;
  return new;
end $$;
drop trigger if exists profiles_notify_member on public.profiles;
create trigger profiles_notify_member after insert on public.profiles for each row execute function public.notify_member();

-- staff replied to a ticket
create or replace function public.notify_ticket() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.from_staff then
    perform notify(t.user_id, 'support', 'mail', 'Support replied', format('#%s · %s', t.ref, t.subject), '#support', 'tm:' || new.id)
      from tickets t where t.id = new.ticket_id;
  end if;
  return new;
end $$;
drop trigger if exists ticket_messages_notify on public.ticket_messages;
create trigger ticket_messages_notify after insert on public.ticket_messages for each row execute function public.notify_ticket();

-- month closed: each investor's own result for the month
create or replace function public.notify_month_close() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform notify(x.user_id, 'month', 'calendar', to_char(new.ym, 'FMMonth YYYY') || ' results booked',
           case when x.pl >= 0 then format('Profit %s added to your balance (after the 2.5%% fee %s).', rs_text(x.pl - x.fee), rs_text(x.fee))
                else format('Loss of %s this month. No fee was charged.', rs_text(-x.pl)) end,
           '#wallet', 'month:' || to_char(new.ym, 'YYYY-MM') || ':' || x.user_id)
    from (select user_id, sum(amount) filter (where type in ('profit', 'loss')) as pl, coalesce(-sum(amount) filter (where type = 'fee'), 0) as fee
            from ledger_entries where ref_type = 'month_close' and ref_id = to_char(new.ym, 'YYYY-MM') group by user_id) x
   where x.pl is not null;
  return new;
end $$;
drop trigger if exists month_closes_notify on public.month_closes;
create trigger month_closes_notify after insert on public.month_closes for each row execute function public.notify_month_close();

-- The signed-in investor marks everything read.
create or replace function public.mark_notifications_read() returns void
language sql security definer set search_path = public as $$
  update notifications set read_at = now() where user_id = auth.uid() and read_at is null
$$;

revoke execute on function public.notify(uuid, text, text, text, text, text, text) from public, anon, authenticated;
revoke execute on function public.mark_notifications_read() from public, anon;
grant execute on function public.mark_notifications_read() to authenticated;

-- ------------------------------------------------------------- public policies
-- The home page's "Company & policies" texts (terms, privacy, complaints, ...). Owner-written (ideally
-- lawyer-reviewed); a policy shows as published only when the owner publishes it.
insert into public.app_settings (key, value) values ('policies', '{}') on conflict (key) do nothing;

create or replace function public.set_policy(p_staff uuid, p_id text, p_text text, p_published boolean) returns text
language plpgsql security definer set search_path = public as $$
declare v_old jsonb;
begin
  perform require_staff(p_staff, array['owner']::staff_role[]);
  if p_id not in ('company', 'contact', 'how', 'strategies', 'fees', 'deposits', 'custody', 'risks', 'eligibility', 'terms', 'privacy', 'complaints') then
    raise exception 'Unknown policy';
  end if;
  if length(coalesce(p_text, '')) > 30000 then raise exception 'Too long (30,000 characters max)'; end if;
  if p_published and length(trim(coalesce(p_text, ''))) < 50 then raise exception 'Write the policy before publishing it'; end if;
  if p_published and p_text ~ '\[[A-Z][^\]]*\]' then raise exception 'Fill in every [BRACKETED] placeholder before publishing'; end if;
  select value -> p_id into v_old from app_settings where key = 'policies';
  update app_settings set value = value || jsonb_build_object(p_id, jsonb_build_object(
           'text', trim(coalesce(p_text, '')), 'published', p_published, 'at', to_char(now() at time zone 'Asia/Karachi', 'DD Mon YYYY'))),
         updated_at = now()
   where key = 'policies';
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, before, after)
  values (p_staff, 'owner', 'policy.' || case when p_published then 'publish' else 'save' end, 'app_settings', p_id,
          case when v_old is not null then jsonb_build_object('published', v_old->'published', 'length', length(v_old->>'text')) end,
          jsonb_build_object('published', p_published, 'length', length(trim(coalesce(p_text, '')))));
  return case when p_published then 'published' else 'saved' end;
end $$;
revoke execute on function public.set_policy(uuid, text, text, boolean) from public, anon, authenticated;
grant execute on function public.set_policy(uuid, text, text, boolean) to service_role;


-- ======================================================== demo_user.sql
-- Demo investor account: mobile 300 1234567, password Demo#2026.
-- Safe to re-run: an existing demo account just gets its password reset.
-- Delete this account before launch (PRODUCTION-BRIEF §9).
do $$
declare
  v_phone text := '923001234567';
  v_uid   uuid;
begin
  select id into v_uid from auth.users where phone = v_phone;
  if v_uid is null then
    v_uid := gen_random_uuid();
    insert into auth.users (
      instance_id, id, aud, role, phone, phone_confirmed_at, encrypted_password,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change,
      phone_change, phone_change_token, email_change_token_current, reauthentication_token)
    values (
      '00000000-0000-0000-0000-000000000000', v_uid, 'authenticated', 'authenticated',
      v_phone, now(), extensions.crypt('Demo#2026', extensions.gen_salt('bf')),
      '{"provider":"phone","providers":["phone"]}',
      jsonb_build_object('full_name', 'Demo Investor', 'email', 'demo@capital50.ai', 'risk_ack_at', now()),
      now(), now(), '', '', '', '', '', '', '', '');
    insert into auth.identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    values (v_uid::text, v_uid,
            jsonb_build_object('sub', v_uid::text, 'phone', v_phone, 'email_verified', false, 'phone_verified', true),
            'phone', now(), now(), now());
  else
    update auth.users
       set encrypted_password = extensions.crypt('Demo#2026', extensions.gen_salt('bf')),
           phone_confirmed_at = coalesce(phone_confirmed_at, now()),
           updated_at = now()
     where id = v_uid;
  end if;
end $$;

-- Demo money: the same sample deposits the dashboard preview used, followed by real month
-- closes, so the demo dashboard shows figures produced by the production ledger.
-- Re-running adds nothing. purge_demo_data() removes all of it.
do $$
declare
  v_uid uuid;
  v_h   uuid;
  d     record;
  m     date;
begin
  select id into v_uid from auth.users where phone = '923001234567';
  for d in select * from (values ('kitchen', date '2026-07-01', 25000, 1), ('gold', date '2026-07-01', 15000, 1),
                                 ('crypto',  date '2026-07-01', 10000, 1), ('sat',  date '2026-09-01', 20000, 4))
                    as v(slug, ym, amt, day) loop
    insert into public.holdings (user_id, strategy_id)
      select v_uid, id from public.strategies where slug = d.slug
      on conflict (user_id, strategy_id) do nothing;
    select h.id into v_h from public.holdings h join public.strategies s on s.id = h.strategy_id
     where h.user_id = v_uid and s.slug = d.slug;
    if not exists (select 1 from public.ledger_entries where idempotency_key = 'demo:deposit:' || d.slug)
       and not exists (select 1 from public.month_closes where ym >= d.ym) then
      insert into public.ledger_entries (user_id, holding_id, type, amount, ym, ref_type, idempotency_key, meta)
      values (v_uid, v_h, 'deposit', d.amt, d.ym, 'demo_seed', 'demo:deposit:' || d.slug,
              jsonb_build_object('demo', true, 'day', d.day));
    end if;
  end loop;

  for m in select generate_series(date '2026-07-01', date '2026-09-01', interval '1 month')::date loop
    if not exists (select 1 from public.month_closes where ym >= m) then
      perform public.close_month(m);
    end if;
  end loop;
end $$;
